const worldSupply={'파르디아 도시 연합':'wood','카르반':'wood','루가르 왕국':'hide','실바족 왕국':'herb','아비에른 왕국':'potion','엘리베른':'ore','노르벨':'hide'};
const worldDemand={'파르디아 도시 연합':'ore','카르반':'hide','루가르 왕국':'wood','실바족 왕국':'ore','아비에른 왕국':'herb','엘리베른':'wood','노르벨':'potion'};
let worldRegion='파르디아 도시 연합',worldCity='벨로른',worldTab='지도';
function worldInit(s){s.world??={visited:{'벨로른':{count:1,first:s.time,last:s.time}},rep:{},history:[],offers:{}};s.world.offers??={};s.world.history??=[];s.world.rep??={};}
function regionData(n=worldRegion){return worldRegions.find(r=>r.name===n)}
function cityData(){return regionData()?.cities.find(c=>c.name===worldCity)}
function worldLocked(c){return ['니벨른','리엔느'].includes(c)}
function ruined(r){return r==='포르카 옛 영토'}
function routeMinutes(r,c){return c==='벨로른'?30:(worldTravel[r]||900)}
function showWorld(tab='지도'){worldTab=tab;screen='세계';selectedQuest=null;notice='';render()}
function selectRegion(n){if(!regionData(n))return;worldRegion=n;worldCity=regionData(n).cities[0].name;worldTab='도시';render()}
function selectWorldCity(n){if(!regionData().cities.some(c=>c.name===n))return;worldCity=n;render()}
function worldLog(t){state.world.history.unshift({time:state.time,text:t});state.world.history=state.world.history.slice(0,150);log(t)}
function worldVisit(q){if(q.visitedRecorded)return;q.visitedRecorded=true;let v=state.world.visited[q.city]??={count:0,first:state.time,last:state.time};v.count++;v.last=state.time;worldLog(q.city+'에 원정대가 도착했다.')}
function worldResult(q,ok){if(q.worldRecorded)return;q.worldRecorded=true;state.world.rep[q.region]=clamp((state.world.rep[q.region]||0)+(ok?3:-1),0,100);worldLog(q.city+' · '+(ok?'지역 의뢰 완료':'원정 미완료')+' · 본부 귀환 및 결과 확인.');}
function rescueQuote(q,count){return {duration:180+(q.travel||0)*2,cost:200+Math.ceil((q.travel||0)/60)*10,food:q.travel?Math.ceil((180+q.travel*2)/480)*count:0}}
function openWorldQuest(kind,mode){let c=cityData(),r=worldRegion;if(!c||worldLocked(c.name))return;let travel=routeMinutes(r,c.name),day=Math.floor(state.time/1440),key=r+':'+c.name+':'+kind+(mode||'');if(state.world.offers[key]===day||state.quests.some(q=>q.city===c.name&&q.worldKind===kind&&(!mode||q.trade?.mode===mode)&&['open',...liveStatuses].includes(q.status)))return;
 let types={visit:['지역 방문 및 연락망 확인','조사',60,22,200],regional:[c.name+' · '+(ruined(r)?'폐허 조사 및 기록 회수':'교통로 및 생활권 안전 조사'),'조사',180,ruined(r)?62:38,ruined(r)?5200:1600],escort:[c.name+' · '+(ruined(r)?'구호 물자 호위':'상단 호위'),'호위',240,ruined(r)?70:50,ruined(r)?7000:3200],trade:[c.name+' · 교역 원정','교역',120,ruined(r)?60:35,0]};let t=types[kind];if(!t||kind==='trade'&&(ruined(r)||!worldSupply[r]))return;let q={id:++state.serial,name:kind==='visit'?c.name+' · '+t[0]:t[0],type:t[1],reward:t[4],duration:travel*2+t[2],difficulty:t[3],status:'open',party:[],report:[],region:r,city:c.name,travel,worldKind:kind,worldOffer:key,offerDay:day};
 if(kind==='visit'&&ruined(r)){q.difficulty=55;q.reward=1000}if(kind==='trade'){if(!['buy','sell'].includes(mode))return;let item=mode==='buy'?worldSupply[r]:worldDemand[r];let qty=Number($('#tradeQty')?.value||3);if(!Number.isInteger(qty)||qty<1||qty>10)return;let unit=tradePrice18(r,item,mode);q.trade={mode,item,qty,unit,total:unit*qty,reserved:false};q.name+=' · '+goods[item].name+' '+qty+'개';}
 state.world.offers[key]=day;state.quests.push(q);screen='의뢰';selectedQuest=q.id;save();render();}
function cancelWorldQuest(id){let q=state.quests.find(q=>q.id===id&&q.city&&q.status==='open');if(!q)return;state.quests=state.quests.filter(x=>x!==q);if(state.world.offers[q.worldOffer]===q.offerDay)delete state.world.offers[q.worldOffer];selectedQuest=null;showWorld('도시');save()}
function tradeReady(q){let t=q.trade;if(!t||t.reserved)return false;return t.mode==='buy'?state.fund>=t.total&&room(t.qty):(state.inventory.goods[t.item]||0)>=t.qty}
function reserveTrade(q){let t=q.trade;if(t.mode==='buy')cash(-t.total,'지역 교역 예약',q.city+' · '+goods[t.item].name);else state.inventory.goods[t.item]-=t.qty;t.reserved=true;}
function finishTrade(q,ok){let t=q.trade;if(!t.reserved)return;t.reserved=false;if(t.mode==='buy'){if(ok)state.inventory.goods[t.item]=(state.inventory.goods[t.item]||0)+t.qty;else cash(t.total,'지역 교역 환불',q.city+' · 미완료 주문')}else{if(ok)cash(t.total,'지역 교역 판매',q.city+' · '+goods[t.item].name);else state.inventory.goods[t.item]=(state.inventory.goods[t.item]||0)+t.qty}worldResult(q,ok);issue(q,ok?'교역 완료 · '+goods[t.item].name+' '+t.qty+'개 · '+money(t.total):'교역 미완료 · 예약금 또는 위탁 물자 반환');}
function worldPanel(){let c=cityData(),r=worldRegion;let head=`<h2>아스테리아 세계</h2><p class="muted">벨로른 본부에서 원정대를 파견합니다. 지아와 본부 직원은 길드에 남습니다.</p><div class="ops-tabs world-tabs">${['지도','도시','원정 기록'].map(t=>`<button class="${worldTab===t?'primary':''}" onclick="showWorld('${t}')">${t}</button>`).join('')}</div>`;
 if(worldTab==='지도')return head+`<div class="card"><h3>확정된 지리 관계</h3><div class="world-map"><div class="world-north"><button onclick="selectRegion('루가르 왕국')">루가르 왕국</button><small>카르반 북쪽~북동쪽 · 인접</small></div><div class="world-west"><button onclick="selectRegion('파르디아 도시 연합')">파르디아 도시 연합</button><small>카르반 서쪽~남서쪽</small></div><div class="world-center"><button onclick="selectRegion('카르반')">카르반</button></div><div class="world-south"><button onclick="selectRegion('실바족 왕국')">실바족 왕국</button><span>동쪽 →</span><button onclick="selectRegion('독립 옛터')">리엔느 옛터</button></div></div><small>상대적 위치만 표현한 개념도. 축척·국경·미확정 좌표 없음. 실바족 왕국의 행은 카르반과의 방향 관계를 뜻하지 않습니다.</small></div><h3>7개 현존 국가 · 포르카 옛 영토</h3>${worldRegions.map(x=>`<button class="wide" onclick="selectRegion('${x.name}')">${x.name} · ${x.cities.length}개 기록 장소${x.name==='파르디아 도시 연합'?' · 본부 소재':''}</button>`).join('')}`;
 if(worldTab==='원정 기록')return head+`<div class="card"><h3>방문 기록 · ${Object.keys(state.world.visited).length}곳</h3>${Object.entries(state.world.visited).map(([n,v])=>`<div class="log">${esc(n)} · ${v.count}회<br><small>최근 ${date(v.last)}</small></div>`).join('')}</div><button class="wide" onclick="go('의뢰')">진행 중인 원정 및 구조 확인</button>${state.world.history.map(h=>`<div class="log"><small>${date(h.time)}</small><br>${esc(h.text)}</div>`).join('')}`;
 let lock=worldLocked(c.name),travel=routeMinutes(r,c.name),market=worldSupply[r]&&!lock&&!ruined(r);let label=state.world.visited[c.name]?'방문 기록 있음':'미방문';let action=(k,n,m='')=>`<button class="wide" onclick="openWorldQuest('${k}','${m}')" ${state.world.offers[r+':'+c.name+':'+k+m]===Math.floor(state.time/1440)||state.quests.some(q=>q.city===c.name&&q.worldKind===k&&(!m||q.trade?.mode===m)&&['open',...liveStatuses].includes(q.status))?'disabled':''}>${n}</button>`;
 return head+`<label>지역<select onchange="selectRegion(this.value)">${worldRegions.map(x=>`<option ${x.name===r?'selected':''}>${x.name}</option>`).join('')}</select></label><label>도시·장소<select onchange="selectWorldCity(this.value)">${regionData().cities.map(x=>`<option ${x.name===c.name?'selected':''}>${x.name}</option>`).join('')}</select></label><div class="card"><div class="eyebrow">${esc(r)} · ${label}</div><h3>${esc(c.name)}</h3><p>${esc(c.desc)}</p><small>산업 및 기능 · ${esc(c.industry)}</small><p><small>환경 · ${esc(c.nature)}</small></p><p><small>위험 정보 · ${esc(c.hazard)}</small></p>${ruined(r)?'<p class="warn">멸망한 옛 영토 · 일반 상업 불가 · 위험 원정</p>':''}${lock?'<p class="warn">정확한 접근 경로가 미확정되어 열람만 가능합니다.</p>':`<p>편도 ${travel/60}시간 · 현지 작업 및 귀환 별도</p><small>게임용 잠정 이동 시간 · ${r==='파르디아 도시 연합'?'도보·마차':'마차·선박 등 복합 이동'} · 지역 평판 ${state.world.rep[r]||0}/100</small>${action('visit','방문 원정 계획')}${action('regional','지역 조사 의뢰 등록')}${action('escort','호위 의뢰 등록')}${historyCity(c.name)}`}</div>${market?`<div class="card"><h3>지역 교역 · 위탁 원정</h3><p>구매 ${goods[worldSupply[r]].name} · ${money(tradePrice18(r,worldSupply[r],'buy'))}/개</p><p>판매 ${goods[worldDemand[r]].name} · ${money(tradePrice18(r,worldDemand[r],'sell'))}/개 · 보유 ${state.inventory.goods[worldDemand[r]]||0}개</p><label>수량<select id="tradeQty">${Array.from({length:10},(_,i)=>`<option ${i===2?'selected':''}>${i+1}</option>`).join('')}</select></label>${action('trade','구매 원정 계획','buy')}${action('trade','판매 원정 계획','sell')}<small>파견 확정 시 대금 또는 물자 예약. 귀환 성공 시 거래 정산. 실패하면 예약금 또는 위탁 물자 반환. 식량 및 준비비는 소모됩니다. 가격은 게임용 임시 수치입니다.</small></div>`:''}`;}



