const monsterBook=__gameData["monsters"];
let historyTab='역사 기록',monsterFilter='',monsterGrade='전체';
function historyInit(s){s.history??={unlocked:{},encounters:{},events:[]};s.history.unlocked??={};s.history.encounters??={};s.history.events??=[];for(let r of historyRecords){if(r.city===null||s.archive.includes(r.title))s.history.unlocked[r.id]??={time:null,source:'기존 소장 기록'};}}
function historyUnlocked(id){return Boolean(state.history.unlocked[id])}
function historyResult(q,ok){if(!ok||!q.historyId||historyUnlocked(q.historyId))return;let r=historyRecords.find(r=>r.id===q.historyId&&r.city===q.city);if(!r)return;state.history.unlocked[r.id]={time:state.time,source:q.city+' 원정 보고'};if(!state.archive.includes(r.title))state.archive.push(r.title);state.history.events.unshift({time:state.time,text:r.title+' 수집 완료'});issue(q,'역사 자료 해금 · '+r.title);}
function historyRegion(city){return worldRegions.find(r=>r.cities.some(c=>c.name===city));}
function historyPending(id){return state.quests.some(q=>q.historyId===id&&['open',...liveStatuses].includes(q.status))}
function planHistory(id){let r=historyRecords.find(r=>r.id===id);if(!r?.city||historyUnlocked(id)||historyPending(id)||worldLocked(r.city))return;let region=historyRegion(r.city);if(!region)return;let travel=routeMinutes(region.name,r.city),day=Math.floor(state.time/1440);let q={id:++state.serial,name:r.city+' · 역사 자료 조사',type:'조사',reward:ruined(region.name)?2400:900,duration:travel*2+120,difficulty:ruined(region.name)?62:30,status:'open',party:[],report:[],region:region.name,city:r.city,travel,worldKind:'history',historyId:id,worldOffer:'history:'+id,offerDay:day};state.quests.push(q);screen='의뢰';selectedQuest=q.id;notice='역사 조사 의뢰를 등록했습니다. 파티를 편성하세요.';save();render();}
function historyCity(city){return historyRecords.filter(r=>r.city===city).map(r=>`<button class="wide" onclick="planHistory('${r.id}')" ${historyUnlocked(r.id)||historyPending(r.id)?'disabled':''}>${historyUnlocked(r.id)?'수집 완료':historyPending(r.id)?'조사 진행 중':'역사 자료 조사'} · ${esc(r.title)}</button>`).join('')}
function heroReady(h){return historyUnlocked(h.need)&&state.rep>=h.rep&&!state.history.encounters[h.id]}
function openHero(id){let h=heroEvents.find(h=>h.id===id);if(!h||!heroReady(h))return;dialogueStart({kind:'hero',hero:id,name:h.name,step:0,asked:[],returnTo:'역사'})}
function heroHome(){let hs=heroEvents.filter(heroReady);return hs.length?`<div class="card"><h3>특별 방문</h3><small>게임 전용 만남 · 공식 영웅은 고용할 수 없습니다.</small>${hs.map(h=>`<div class="person history-person">${portrait(h.name)}<div><b>${esc(h.name)}</b><button class="wide primary" onclick="openHero('${h.id}')">대화하기</button></div></div>`).join('')}</div>`:''}
function showHistory(t='역사 기록'){historyTab=t;screen='역사';selectedQuest=null;notice='';render()}
function filterMonsters(v){monsterFilter=v;renderMonsterList()}
function gradeMonsters(v){monsterGrade=v;renderMonsterList()}
function monsterList(){let term=monsterFilter.trim().toLowerCase();let ms=monsterBook.filter(m=>(monsterGrade==='전체'||m.등급===monsterGrade)&&[m.name,m.서식지,m['능력·특징']].some(v=>String(v||'').toLowerCase().includes(term)));return `<p class="muted">${ms.length} / ${monsterBook.length}종</p>`+ms.map(m=>`<details class="card monster-entry"><summary><b>${esc(m.name)}</b> · ${esc(m.등급||'미확인')}급<br><small>${esc(m.서식지||'미확인')} · ${esc(m['능력·특징']||'')}</small></summary><div class="monster-facts">${Object.entries(m).filter(([k])=>!['id','name','등급','서식지','능력·특징'].includes(k)).map(([k,v])=>`<div><small>${esc(k)}</small><p>${esc(v)}</p></div>`).join('')}</div></details>`).join('')}
function renderMonsterList(){let el=$('#monster-list');if(el)el.innerHTML=monsterList()}
function historyPanel(){let head=`<h2>역사 아카이브</h2><p class="muted">오래된 발자취와 길드가 남기는 새로운 기록. 자료 조사·방문 대사는 게임 전용이며 본편 사건을 확정하지 않습니다.</p><div class="ops-tabs history-tabs">${['역사 기록','몬스터 도감','영웅 방문','수집 기록'].map(t=>`<button class="${historyTab===t?'primary':''}" onclick="showHistory('${t}')">${t}</button>`).join('')}</div>`;
if(historyTab==='몬스터 도감')return head+`<div class="card"><h3>카르코의 기록 · 후대 도감</h3><small>설정집의 80종 생태 기록을 옮긴 자료. 대표 추정치 및 원문 기록이며, 전투 능력치와 별개입니다.</small><label>이름·서식지·특징 검색<input id="monster-search" value="${esc(monsterFilter)}" oninput="filterMonsters(this.value)" placeholder="앰버테일, 카르반 등"></label><label>위험 등급<select onchange="gradeMonsters(this.value)">${['전체',...new Set(monsterBook.map(m=>m.등급))].map(g=>`<option ${g===monsterGrade?'selected':''}>${esc(g)}</option>`).join('')}</select></label></div><div id="monster-list">${monsterList()}</div>`;
if(historyTab==='영웅 방문')return head+`<p class="muted">기록 해금과 길드 평판이 방문 조건입니다. 본편 인물의 실제 여정이나 날짜와 별개인 가상 만남입니다. 일반 계약·파견·연애 대상이 아닙니다.</p>`+heroEvents.map(h=>{let done=state.history.encounters[h.id],ready=heroReady(h);return `<div class="card person history-person">${portrait(h.name)}<div><h3>${esc(h.name)}</h3><small>${done?'방문 완료 · '+date(done.time):ready?'방문 가능':'평판 '+h.rep+' · '+esc(historyRecords.find(r=>r.id===h.need).title)+' 필요'}</small>${ready?`<button class="wide primary" onclick="openHero('${h.id}')">대화하기</button>`:''}</div></div>`}).join('');
if(historyTab==='수집 기록')return head+`<h3>자료 수집 연혁</h3>${state.history.events.map(e=>`<div class="log"><small>${date(e.time)}</small><br>${esc(e.text)}</div>`).join('')||'<p class="muted">아직 원정에서 수집한 자료가 없습니다.</p>'}<h3>영웅과의 대화 기록</h3>${state.conversations.filter(c=>heroEvents.some(h=>h.name===c.with)).slice().reverse().map(c=>`<div class="log"><small>${date(c.time)} · ${esc(c.with)}</small><br>${esc(c.speaker)}: ${esc(c.line)}</div>`).join('')||'<p class="muted">아직 대화 기록이 없습니다.</p>'}`;
return head+`<div class="card"><h3>소장 기록 ${historyRecords.filter(r=>historyUnlocked(r.id)).length} / ${historyRecords.length}</h3><div class="bar"><b style="width:${historyRecords.filter(r=>historyUnlocked(r.id)).length/historyRecords.length*100}%"></b></div><small>지역 조사 의뢰를 성공적으로 마치고 귀환하면 해당 기록을 해금합니다.</small></div>`+historyRecords.map(r=>{let u=state.history.unlocked[r.id],pending=historyPending(r.id);return `<div class="card"><div class="person history-person">${u&&r.person?portrait(r.person):''}<div><small>${esc(r.era)} · ${u?'소장 중':pending?'조사 진행 중':'미수집'}</small><h3>${esc(r.title)}</h3></div></div>${u?`<p>${esc(r.text)}</p><small>${esc(u.source)}${u.time===null?'':' · '+date(u.time)}</small>`:`<p class="muted">조사 장소: ${esc(r.city)}</p><button class="wide primary" onclick="planHistory('${r.id}')" ${pending?'disabled':''}>${pending?'조사 진행 중':'조사 원정 등록'}</button>`}</div>`}).join('')+state.archive.filter(t=>!historyRecords.some(r=>r.title===t)).map(t=>`<div class="card"><small>이전 버전에서 보존한 기록</small><p>${esc(t)}</p></div>`).join('');}



// v0.9: game-only story progression and choice events.
const storyChapters=[
{id:'first',title:'1장 · 꺼져 가던 등불',speaker:'에린 로웰',line:'새 길드장님. 작은 의뢰부터 차근차근 쌓아 가면, 다시 이곳을 찾아오는 사람들이 생길 거예요.',end:'아직 작지만, 길드에 다시 일상의 소리가 들리기 시작했다.',goals:[['의뢰 3건 완료',()=>state.completed>=3,()=>`${Math.min(3,state.completed)}/3`],['지역 평판 25 이상',()=>state.rep>=25,()=>`${state.rep}/25`]],reward:300},
{id:'people',title:'2장 · 함께 걷는 사람들',speaker:'로웬 하르트',line:'길드의 힘은 서류에 적힌 인원수가 아니야. 사람들이 안심하고 돌아올 수 있는 곳이어야 하지.',end:'길드의 문은 이제 서로를 기다리는 사람들의 장소가 되었다.',goals:[['소속 모험가 6명 이상',()=>state.people.filter(currentMember).length>=6,()=>`${state.people.filter(currentMember).length}/6`],['의무실 2레벨 이상',()=>facilityLevel('clinic')>=2,()=>`${facilityLevel('clinic')}/2`]],reward:500},
{id:'trust',title:'3장 · 신뢰의 무게',speaker:'마레트 에스카르',line:'신뢰는 장부에 숫자로 남지 않지만, 장부를 제대로 관리하지 않으면 가장 먼저 사라집니다.',end:'길드는 사람들의 신뢰를 잃지 않기 위해 스스로의 운영 원칙을 세웠다.',goals:[['평판 40 이상',()=>state.rep>=40,()=>`${state.rep}/40`],['직원 및 모험가 미지급 급여 없음',()=>state.economy.staff.every(p=>!p.arrears)&&state.people.filter(currentMember).every(p=>!p.arrears),()=>state.economy.staff.every(p=>!p.arrears)&&state.people.filter(currentMember).every(p=>!p.arrears)?'충족':'미충족'],['운영 자금 3 G 이상',()=>state.fund>=30000,()=>money(state.fund)]],reward:700},
{id:'world',title:'4장 · 멀리 이어지는 길',speaker:'테오 바실',line:'우리가 모은 기록과 원정 보고서가 다른 사람들에게도 도움이 될 수 있겠어요.',end:'벨로른에서 켜진 작은 등불은 먼 곳의 길까지 비추기 시작했다.',goals:[['지역 의뢰 3건 성공',()=>state.quests.filter(q=>q.city&&q.status==='success'&&!q.trade).length>=3,()=>`${state.quests.filter(q=>q.city&&q.status==='success'&&!q.trade).length}/3`],['역사 기록 4종 이상',()=>Object.keys(state.history.unlocked).length>=4,()=>`${Object.keys(state.history.unlocked).length}/4`]],reward:1000},
{id:'lantern',title:'5장 · 길의 등불',speaker:'지아 메르벨',line:'우리가 세운 이곳이 떠나는 사람에게는 출발점이, 돌아오는 사람에게는 집이 되었으면 좋겠다.',end:'길드의 재건은 끝이 아니라 다음 모험의 시작이다.',goals:[['평판 60 이상',()=>state.rep>=60,()=>`${state.rep}/60`],['누적 의뢰 20건 완료',()=>state.completed>=20,()=>`${state.completed}/20`],['시설 3곳 이상 2레벨',()=>Object.values(state.economy.facilities).filter(v=>v>=2).length>=3,()=>`${Object.values(state.economy.facilities).filter(v=>v>=2).length}/3`]],reward:1500}
];
const storyEvents=window.__gameData["story-events"];
let storyTab='메인 이야기';
function storyInit(s){s.story??={chapter:0,finished:[],pending:null,lastDay:Math.floor(s.time/1440),lastSpawn:-99,events:[],seen:{}};s.story.finished??=[];s.story.events??=[];s.story.seen??={};}
function storyRecord(text,kind='사건'){state.story.events.unshift({time:state.time,kind,text});if(state.story.events.length>200)state.story.events.length=200;log(text);}
function dailyStory(){let day=Math.floor(state.time/1440),v=state.story;if(day<=v.lastDay)return;v.lastDay=day;if(v.pending||day-v.lastSpawn<2||Math.random()>.6)return;let pool=storyEvents.filter(e=>day-(v.seen[e.id]??-99)>=7);if(!pool.length)return;let e=pick(pool);v.pending={id:e.id,day};v.lastSpawn=day;storyRecord('새로운 사건: '+e.title,'알림');}
function storyOptionOK(o){return state.fund>=(o.cost||0)&&state.food+(o.food||0)<=capacity()&&(!o.applicants||state.applicants.length<APPLICANT_CAP)}
function resolveStoryEvent(id,i){let pending=state.story.pending,e=storyEvents.find(e=>e.id===id),o=e?.opts[i];if(!pending||pending.id!==id||!o||!storyOptionOK(o)||state.dialogue)return;if(o.cost&&!cash(-o.cost,'이야기 사건',e.title))return;if(o.income)cash(o.income,'이야기 사건',e.title);state.food+=o.food||0;state.rep=clamp(state.rep+(o.rep||0),0,100);state.facility=clamp(state.facility+(o.facility||0),0,100);for(let p of state.economy.staff.slice(1)){p.morale=clamp(p.morale+(o.morale||0),0,100);p.fatigue=clamp(p.fatigue+(o.fatigue||0),0,100)}if(o.applicants)arrive(Math.min(o.applicants,APPLICANT_CAP-state.applicants.length),'환영 행사');state.story.seen[id]=Math.floor(state.time/1440);state.story.pending=null;storyRecord(e.title+' · '+o.result);notice=o.result;save();if(o.minutes)advance(o.minutes);else render()}
function completeChapter(id){let c=storyChapters[state.story.chapter];if(!c||c.id!==id||state.story.finished.some(f=>f.id===id)||!c.goals.every(g=>g[1]())||state.dialogue)return;state.story.finished.push({id,time:state.time});state.story.chapter++;cash(c.reward,'재건 지원금',c.title);storyRecord(c.title+' 완료 · '+c.end,'장 완료');notice='재건 목표 달성 · 지원금 '+money(c.reward);if(state.story.chapter>=storyChapters.length){unlockEnding('rebuilt');screen='엔딩';endingSelected='rebuilt'}save();render()}
function showStory(tab='메인 이야기'){storyTab=tab;screen='이야기';selectedQuest=null;selectedPerson=null;notice='';render()}
function storyHome(){let c=storyChapters[state.story.chapter],e=storyEvents.find(e=>e.id===state.story.pending?.id);return `<div class="card"><div class="eyebrow">길드 재건 이야기</div><h3>${esc(c?.title||'길드 재건 달성')}</h3><small>${state.story.finished.length} / ${storyChapters.length}장 완료${e?' · 새 사건 1건':''}</small><button class="wide primary" onclick="showStory('${e?'사건':'메인 이야기'}')">${e?'새 사건 확인 · '+esc(e.title):'이야기 및 목표 확인'}</button></div>`}
function storyPanel(){let v=state.story,c=storyChapters[v.chapter],e=storyEvents.find(e=>e.id===v.pending?.id);let head=`<h2>다시 타오르는 등불</h2><p class="muted">지아와 길드의 재건을 그린 게임 전용 이야기입니다. 본편 캐논을 변경하지 않습니다.</p><div class="ops-tabs story-tabs">${['메인 이야기','사건','연대기'].map(t=>`<button class="${storyTab===t?'primary':''}" onclick="showStory('${t}')">${t}${t==='사건'&&e?' · 1':''}</button>`).join('')}</div>`;
if(storyTab==='사건')return head+(e?`<div class="card"><div class="eyebrow">길드 사건</div><div class="person">${portrait(e.speaker)}<div><h3>${esc(e.title)}</h3><small>${esc(e.speaker)}</small></div></div><p>${esc(e.body)}</p>${e.opts.map((o,i)=>`<button class="wide ${i===0?'primary':''}" onclick="resolveStoryEvent('${e.id}',${i})" ${storyOptionOK(o)&&!state.dialogue?'':'disabled'}>${esc(o.label)}</button>`).join('')}<small>선택 전까지 사건은 보관됩니다. 자금·창고·모집 한도에 따라 선택이 제한됩니다.</small></div>`:'<div class="card"><p>현재 해결할 사건이 없습니다.</p><small>게임 속 시간이 지나면 새로운 사건이 발생할 수 있습니다.</small></div>');
if(storyTab==='연대기')return head+(v.events.map(e=>`<div class="log"><small>${date(e.time)} · ${esc(e.kind)}</small><br>${esc(e.text)}</div>`).join('')||'<p class="muted">아직 기록이 없습니다.</p>');
return head+`<div class="card"><h3>재건 진행 ${v.finished.length} / ${storyChapters.length}</h3><div class="bar"><b style="width:${v.finished.length/storyChapters.length*100}%"></b></div></div>`+(c?`<div class="card"><div class="person">${portrait(c.speaker)}<div><h3>${esc(c.title)}</h3><small>${esc(c.speaker)}</small></div></div><p>${esc(c.line)}</p>${c.goals.map(g=>`<div class="story-goal"><span>${g[1]()?'✓':'○'} ${esc(g[0])}</span><b>${esc(g[2]())}</b></div>`).join('')}<small>재건 지원금 ${money(c.reward)} · 게임용 보상</small><button class="wide primary" onclick="completeChapter('${c.id}')" ${c.goals.every(g=>g[1]())&&!state.dialogue?'':'disabled'}>장 완료 · 지원금 받기</button></div>`:'<div class="card"><h3>길드 재건 목표 달성</h3><p>새로운 의뢰와 사람들은 여전히 기다리고 있습니다. 같은 저장으로 자유 경영을 계속할 수 있습니다.</p></div>')+storyChapters.map((x,i)=>`<div class="card"><small>${i<v.chapter?'완료':i===v.chapter?'진행 중':'미해금'}</small><h3>${esc(x.title)}</h3>${i<v.chapter?`<p>${esc(x.end)}</p>`:''}</div>`).join('');}



// v1.0: collectible endings; every ending preserves the same playable save.
let endingSelected=null;
function arrearsTotal(){return [...state.economy.staff,...state.people.filter(currentMember)].reduce((n,p)=>n+(p.arrears||0),0)}
function endingStats(){return {day:Math.floor(state.time/1440),fund:state.fund,rep:state.rep,completed:state.completed,members:state.people.filter(currentMember).length,memorial:state.memorial.length,history:Object.keys(state.history.unlocked).length,rescued:state.endings.rescued}}
function lowRiskSuccess(){return state.quests.filter(q=>q.status==='success'&&!q.trade&&q.policy==='safe').length}
function endingRegions(){return new Set(state.quests.filter(q=>q.status==='success'&&q.region&&!q.trade).map(q=>q.region)).size}
const endings=[
 {id:'rebuilt',kind:'성공',title:'다시 타오르는 등불',text:'길드의 문을 다시 열었던 날부터, 지아는 수없이 많은 선택을 했다. 이제 돌아오는 사람들을 기다리는 불빛은 혼자 지키는 것이 아니다.',goals:[['메인 이야기 5장 완료',()=>state.story.chapter>=5,()=>state.story.chapter+'/5']]},
 {id:'safe',kind:'성공',title:'모두의 귀환',text:'길의 등불은 가장 강한 길드가 아니라, 동료를 버리지 않는 길드로 기억되었다.',goals:[['생존 우선 의뢰 20건 성공',()=>lowRiskSuccess()>=20,()=>lowRiskSuccess()+'/20'],['사망 기록 0명',()=>state.memorial.length===0,()=>state.memorial.length+'명'],['현재 실종·귀환 지연·구조 중 없음',()=>!state.quests.some(q=>['missing','delayed','rescuing'].includes(q.status)),()=>state.quests.some(q=>['missing','delayed','rescuing'].includes(q.status))?'미충족':'충족'],['평판 70 이상',()=>state.rep>=70,()=>state.rep+'/70']]},
 {id:'prosper',kind:'성공',title:'번영의 등불',text:'마레트는 장부를 덮었다. 이제 내일의 급여를 걱정하기보다, 다음 세대의 길을 준비할 수 있다.',goals:[['운영 자금 15 G 이상',()=>state.fund>=150000,()=>money(state.fund)],['모든 시설 3레벨 이상',()=>Object.values(state.economy.facilities).every(v=>v>=3),()=>Object.values(state.economy.facilities).filter(v=>v>=3).length+'/5'],['미지급 급여 없음',()=>arrearsTotal()===0,()=>money(arrearsTotal())]]},
 {id:'historian',kind:'특수',title:'기억을 잇는 사람들',text:'오래전의 영웅은 돌아오지 않는다. 그러나 기록을 읽는 새로운 사람들이 그 길을 다시 걷는다.',goals:[['역사 자료 8종 수집',()=>historyRecords.every(r=>historyUnlocked(r.id)),()=>historyRecords.filter(r=>historyUnlocked(r.id)).length+'/8'],['특별 영웅 방문 5명',()=>heroEvents.every(h=>!!state.history.encounters[h.id]),()=>heroEvents.filter(h=>!!state.history.encounters[h.id]).length+'/5']]},
 {id:'roads',kind:'특수',title:'국경 너머의 등불',text:'낯선 도시에서도 길의 등불이라는 이름을 알아보는 사람들이 생겼다. 길은 국경에서 끝나지 않았다.',goals:[['서로 다른 8개 국가·옛 영토에서 지역 의뢰 성공',()=>endingRegions()>=8,()=>endingRegions()+'/8'],['평판 80 이상',()=>state.rep>=80,()=>state.rep+'/80']]},
 {id:'distress',kind:'실패',title:'흔들리는 불꽃',text:'빈 장부와 미지급 급여 앞에서 지아는 실패를 인정했다. 그러나 문을 닫는 대신, 다시 일어설 방법을 찾기로 했다.',goals:[['자금 1 S 미만과 급여 체불 상태가 3일 연속',()=>state.endings.distressDays>=3,()=>state.endings.distressDays+'/3']]},
 {id:'recovery',kind:'특수',title:'재에서 피어난 불빛',text:'한 번 꺼질 뻔한 등불을 다시 살렸다. 실패는 길드의 마지막 문장이 아니었다.',goals:[['흔들리는 불꽃 엔딩 열람',()=>!!state.endings.unlocked.distress,()=>state.endings.unlocked.distress?'충족':'미충족'],['급여 체불 전액 정산',()=>arrearsTotal()===0,()=>money(arrearsTotal())],['운영 자금 3 G 이상',()=>state.fund>=30000,()=>money(state.fund)],['평판 50 이상',()=>state.rep>=50,()=>state.rep+'/50']]}
];
function endingInit(s){s.endings??={};let e=s.endings;e.unlocked??={};e.rescued??=0;e.distressDays??=0;e.lastDay??=Math.floor(s.time/1440);}
function dailyEnding(){let e=state.endings,day=Math.floor(state.time/1440);if(day<=e.lastDay)return;e.lastDay=day;e.distressDays=state.fund<100&&arrearsTotal()>0?e.distressDays+1:0;}
function endingReady(e){return e.goals.every(g=>g[1]());}
function unlockEnding(id){let e=endings.find(e=>e.id===id);if(!e||state.endings.unlocked[id]||!endingReady(e))return false;state.endings.unlocked[id]={time:state.time,stats:endingStats()};storyRecord('엔딩 달성 · '+e.title,'엔딩');return true;}
function claimEnding(id){if(state.dialogue||!unlockEnding(id))return;endingSelected=id;notice='엔딩 기록을 보존했습니다. 같은 저장으로 계속할 수 있습니다.';save();render();}
function showEndings(id=null){if(state.dialogue){go('대화');return}endingSelected=id;screen='엔딩';notice='';render();}
function continueGuild(){endingSelected=null;go('길드');save();}
function endingHome(){let n=Object.keys(state.endings.unlocked).length,r=endings.filter(e=>!state.endings.unlocked[e.id]&&endingReady(e)).length;return `<div class="card ending-home"><div class="row"><div><small>길드의 발자취</small><h3>${n?'엔딩 도감 · 자유 경영':'길드의 미래'}</h3></div><b>${n}/${endings.length}</b></div><div class="bar"><b style="width:${n/endings.length*100}%"></b></div><button class="wide" onclick="showEndings()">${r?'달성 가능한 엔딩 '+r+'개':'엔딩 및 장기 목표 확인'}</button></div>`;}
function endingPanel(){let e=endings.find(e=>e.id===endingSelected),record=e&&state.endings.unlocked[e.id],n=Object.keys(state.endings.unlocked).length;let head=`<h2>길의 끝, 또 다른 시작</h2><p class="muted">엔딩은 게임 전용 기록입니다. 어떤 엔딩도 게임을 종료하거나 저장을 초기화하지 않습니다.</p>`;if(record){let t=record.stats;return head+`<section class="card ending-scene"><div class="eyebrow">${esc(e.kind)} 엔딩 · ${date(record.time)}</div><div class="dialogue-art">${portrait('지아 메르벨')}</div><h1>${esc(e.title)}</h1><p>${esc(e.text)}</p><div class="grid"><div class="card"><small>달성 당시 평판</small><div class="value">${t.rep}</div></div><div class="card"><small>완료 의뢰</small><div class="value">${t.completed}</div></div><div class="card"><small>동료</small><div class="value">${t.members}</div></div><div class="card"><small>운영 자금</small><div class="value">${money(t.fund)}</div></div></div><button class="wide primary" onclick="continueGuild()">같은 저장으로 자유 경영 계속</button><button class="wide" onclick="showEndings()">엔딩 도감으로</button></section>`;}return head+`<div class="card"><h3>수집한 엔딩 ${n} / ${endings.length}</h3><div class="bar"><b style="width:${n/endings.length*100}%"></b></div><button class="wide" onclick="continueGuild()">길드로 돌아가기</button></div>`+endings.map(e=>{let got=state.endings.unlocked[e.id],ready=endingReady(e);return `<div class="card ending-card"><div class="row"><small>${esc(e.kind)} 엔딩</small><small class="${got?'good':''}">${got?'수집 완료':ready?'달성 가능':'미달성'}</small></div><h3>${esc(e.title)}</h3>${got?`<small>${date(got.time)}</small><button class="wide" onclick="showEndings('${e.id}')">다시 보기</button>`:e.goals.map(g=>`<div class="story-goal"><span>${g[1]()?'✓':'○'} ${esc(g[0])}</span><b>${esc(g[2]())}</b></div>`).join('')+`<button class="wide primary" onclick="claimEnding('${e.id}')" ${ready?'':'disabled'}>엔딩 기록하기</button>`}</div>`}).join('');}



// v1.2: presentation state only. No changes to the saved simulation schema.
let uiTab='소속',uiSearch='',uiStatus='전체',uiClock=false,uiLastKey='';
const uiPaths={home:'M3 10 12 3l9 7v10h-6v-7H9v7H3z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M16 4a4 4 0 0 1 0 7 M22 21v-2a4 4 0 0 0-3-4',quest:'M5 3h11l3 3v15H5z M9 9h6 M9 13h6 M9 17h4',city:'M3 21V9h7V3h4v10h7v8z M6 13h1 M6 17h1 M17 17h1',menu:'M4 6h16 M4 12h16 M4 18h16',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',coins:'M5 7c0-4 14-4 14 0s-14 4-14 0 M5 7v5c0 4 14 4 14 0V7 M5 12v5c0 4 14 4 14 0v-5',bag:'M8 7V5a4 4 0 0 1 8 0v2 M4 7h16l1 14H3z',heart:'M12 21 3 12a5 5 0 0 1 9-5 5 5 0 0 1 9 5z',book:'M12 5v16 M12 5C9 2 5 2 2 4v15c4-2 7-1 10 2 3-3 6-4 10-2V4c-3-2-7-2-10 1',globe:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M2 12h20 M12 2c-7 7-7 13 0 20 7-7 7-13 0-20',lantern:'M9 3h6 M12 3v3 M7 6h10l-1 3 3 10H5L8 9z M8 9h8 M12 12c-4 4 3 7 3 2-1 1-2-1-3-2 M7 22h10'};
function uiIcon(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${uiPaths[n]||uiPaths.menu}"/></svg>`}
function uiFilter(){let query=uiSearch.trim().toLowerCase();let list=$('#'+(uiTab==='모집'?'recruit':'member')+'-list');if(!list)return;let count=0;list.querySelectorAll('[data-search]').forEach(e=>{let yes=(!query||e.dataset.search.toLowerCase().includes(query))&&(uiTab==='모집'||uiStatus==='전체'||e.dataset.status===uiStatus);e.hidden=!yes;if(yes)count++});let result=$('#ui-results');if(result)result.textContent=count+'명 표시';}
function uiSetTab(t){uiTab=t;uiSearch='';uiStatus='전체';render();window.scrollTo(0,0)}
function uiClockToggle(){uiClock=!uiClock;let p=$('#time-panel'),b=$('#time-toggle');if(p)p.hidden=!uiClock;if(b){b.setAttribute('aria-expanded',String(uiClock));b.querySelector('span').textContent=uiClock?'−':'+'}}
function uiRecruitScreen(){let rec=$('#recruit-list'),mem=$('#member-list'),banner=$('.recruit-banner');if(!rec||!mem||!banner)return;if(uiTab==='소속'&&uiStatus!=='전체'&&!state.people.filter(currentMember).some(p=>p.status===uiStatus))uiStatus='전체';let main=$('main'),title=main.querySelector('h2');let toolbar=document.createElement('section');toolbar.className='roster-toolbar';toolbar.innerHTML=`<div class="roster-switch" role="group" aria-label="모험가 목록 종류">${['소속','모집'].map(t=>`<button aria-pressed="${uiTab===t}" class="${uiTab===t?'primary':''}" onclick="uiSetTab('${t}')">${t} <b>${t==='소속'?state.people.filter(currentMember).length:state.applicants.length}</b></button>`).join('')}</div><label class="search-label" for="ui-search">이름 · 직업 · 종족 검색</label><input id="ui-search" type="search" placeholder="모험가 검색" value="${esc(uiSearch)}" oninput="uiSearch=this.value;uiFilter()"><div class="filter-line">${uiTab==='소속'?`<label for="ui-status">상태</label><select id="ui-status" onchange="uiStatus=this.value;uiFilter()">${['전체',...new Set(state.people.filter(currentMember).map(p=>p.status))].map(t=>`<option ${t===uiStatus?'selected':''}>${esc(t)}</option>`).join('')}</select>`:''}<small id="ui-results" aria-live="polite"></small></div>`;title.after(toolbar);rec.hidden=uiTab!=='모집';banner.hidden=uiTab!=='모집';mem.hidden=uiTab!=='소속';uiFilter()}
function uiHome(){let main=$('main'),hero=main.querySelector('.hero');if(!hero)return;let shortcut=document.createElement('section');shortcut.className='quick-grid';shortcut.setAttribute('aria-label','빠른 메뉴');let shortcuts=[['quest','의뢰 게시판',"go('의뢰')"],['users','신규 모집',"uiTab='모집';go('모험가')"],['coins','길드 운영',"showEconomy('재정')"],['bag','창고·장비',"showInventory('창고')"],['heart','인간관계','showSocial()'],['globe','세계 원정','showWorld()'],['book','역사 기록','showHistory()'],['lantern','이야기','showStory()']];shortcut.innerHTML=shortcuts.map(([i,t,a])=>`<button onclick="${a}">${uiIcon(i)}<span>${t}</span></button>`).join('');let stats=hero.nextElementSibling;stats.classList.add('home-stats');stats.after(shortcut);let old=main.querySelectorAll(':scope > button');old.forEach(b=>{if(b.textContent.startsWith('길드 운영 ·')||b.textContent.startsWith('인간관계 ·'))b.remove()});let urgent=state.quests.filter(q=>['missing','delayed','rescuing'].includes(q.status)).length;if(urgent){let box=document.createElement('div');box.className='card urgent';box.innerHTML=`<h3>긴급 상황 ${urgent}건</h3><button class="wide" onclick="go('의뢰')">실종·귀환 지연·구조 확인 →</button>`;hero.after(box)}}
function render(){let oldY=window.scrollY;let key=state?[screen,selectedPerson,screen==='운영'?economyTab:'',screen==='모험가'?uiTab:'',screen==='대화'?state.dialogue?.step:''].join('|'):'title';let changed=key!==uiLastKey;uiLastKey=key;renderCore();let app=$('#app');app.dataset.screen=state?screen:'title';if(!state){let l=$('.lantern');if(l)l.innerHTML=uiIcon('lantern');return}let nav=$('nav'),header=$('header'),main=$('main');let names=['home','users','quest','city','menu'];nav.querySelectorAll('button').forEach((b,i)=>{b.querySelector('span').innerHTML=uiIcon(names[i]);if(b.classList.contains('active'))b.setAttribute('aria-current','page')});nav.setAttribute('aria-label','주 메뉴');let eyebrow=header.querySelector('.eyebrow');eyebrow.innerHTML=`<span>ASTERIA <i>·</i> 길의 등불</span><span class="screen-label">${esc(screen)}</span>`;let moneyRow=header.querySelector('.row');moneyRow.classList.add('hud');moneyRow.querySelector('strong').insertAdjacentHTML('afterbegin',uiIcon('coins'));let oldTime=main.lastElementChild;if(screen!=='대화'&&oldTime?.textContent.includes('시간 진행 · 현실 시간과 무관')){oldTime.remove();let dock=document.createElement('section');dock.className='time-dock';dock.innerHTML=`<div id="time-panel" ${uiClock?'':'hidden'}><small>게임 속 시간만 흐릅니다.</small><div class="actions">${[30,60,180,480].map(m=>`<button onclick="advance(${m})">+${m===30?'30분':m/60+'시간'}</button>`).join('')}</div></div><button id="time-toggle" aria-expanded="${uiClock}" aria-controls="time-panel" onclick="uiClockToggle()">${uiIcon('clock')} 시간 진행 <span>${uiClock?'−':'+'}</span></button>`;nav.before(dock)}else uiClock=false;
if(screen==='길드')uiHome();if(screen==='모험가'&&!selectedPerson)uiRecruitScreen();if(screen==='대화'){let art=$('.dialogue-art');if(art)art.classList.add('visual-novel-art');}
if(changed)window.scrollTo(0,0);else window.scrollTo(0,oldY);}

// v1.2 — persistent conversations, authored voices and generated biographies.
const voice12={
 '신중함':['먼저 상황을 살펴보고 싶습니다.','조금 더 생각해 보겠습니다.','확실한 약속이라면 믿을 수 있겠습니다.'], '성실함':['맡겨 주신 일은 끝까지 해내겠습니다.','차근차근 해보겠습니다.','기억해 두겠습니다.'], '낙천적':['오늘은 꽤 좋은 날인 것 같아요!','한 번 해보죠!','그렇게 말해 주니 힘이 나네요!'], '독립적':['제 방식대로 해보고 싶습니다.','결정은 제가 하고 싶군요.','제 선택을 존중해 주셔서 고맙습니다.'], '책임감':['동료들에게 피해가 가지 않았으면 합니다.','맡은 책임은 다하겠습니다.','그 말씀, 잊지 않겠습니다.'], '사교적':['마침 이야기하고 싶었어요!','이야기하다 보니 시간이 금방 가네요.','고마워요! 다음에 또 이야기해요.'], '과묵함':['…무슨 일이죠?','알겠습니다.','…고맙습니다.'], '호기심':['궁금한 게 많은 하루예요.','그건 좀 더 알아보고 싶네요.','좋은 생각이에요. 기억할게요.'], '끈기':['쉽지 않아도 계속 해보겠습니다.','시간이 걸려도 괜찮습니다.','그 말 덕분에 다시 해볼 마음이 생깁니다.'], '느긋함':['급할 건 없잖아요. 이야기해요.','천천히 생각해 보죠.','덕분에 마음이 한결 편해졌어요.'], '완벽주의':['빠뜨린 부분이 없는지 확인하고 있습니다.','조건을 분명히 해두고 싶습니다.','구체적으로 말씀해 주셔서 감사합니다.'], '즉흥적':['오늘은 무슨 재미있는 일이 있나요?','일단 해보면 알겠죠!','좋아요, 그렇게 해봐요!']};
const bio12={ '농경 가정':['수확기에 가족의 일을 도왔어요.','흉작을 겪으며 식량의 소중함을 배웠어요.','어릴 때부터 계절마다 달라지는 일을 배웠어요.'], '어업 가정':['어릴 때부터 물가에서 일했어요.','날씨를 살피는 버릇이 몸에 배었어요.','그물 손질과 물자 운반을 도왔어요.'], '상인 가정':['장터에서 물건을 정리하며 자랐어요.','상단의 짐을 챙기는 일을 배웠어요.','손님과 가격을 조율하는 모습을 보며 컸어요.'], '장인 가정':['작업장에서 도구 손질을 도왔어요.','물건 하나를 만드는 데 얼마나 손이 가는지 알아요.','재료를 구분하는 일을 배웠어요.'], '도시 노동자 가정':['일거리를 찾아 여러 작업장을 다녔어요.','동네 사람들과 서로 도우며 지냈어요.','몸을 써서 생활비를 마련해 왔어요.'], '군 복무 경험':['물자 점검과 교대 근무를 경험했어요.','함께 움직이는 일의 중요성을 배웠어요.','명령과 현장의 차이를 경험했어요.'], '학업 및 연구 경험':['자료를 정리하고 기록하는 일을 배웠어요.','이론과 실제가 다를 때가 많더군요.','배운 지식을 현장에서 써보고 싶어요.'], '장기 여행 경험':['낯선 마을에서 작은 일거리를 맡았어요.','여행 중 장비와 식량을 아끼는 법을 배웠어요.','여러 지역에서 사람들의 생활을 지켜봤어요.']};
const habits12=['아침에 장비를 점검하기','틈날 때 산책하기','따뜻한 차 마시기','작은 물건 수집하기','여행 기록 남기기','동료와 식사하기','조용히 책 읽기','잠들기 전 하루 정리하기'];
const concerns12=['낯선 동료와 호흡 맞추기','생활비 마련','충분한 휴식 확보','실력 부족에 대한 걱정','위험한 의뢰에 대한 불안','고향 소식 기다리기'];
