function bioInit12(p){if(!p.generated||p.bio12)return;let h=hash12(p.name+'|'+p.id),b=bio12[p.profile?.background];p.bio12={detail:b?b[h%b.length]:'여러 일을 경험하며 지냈어요.',habit:habits12[(h>>>5)%habits12.length],concern:concerns12[(h>>>11)%concerns12.length]}}
