function mMigrate13(s){for(let q of s.quests.filter(q=>q.status==='open'&&!q.monsterId)){if(q.name==='앰버테일 접근 조사'){let travel=routeMinutes('카르반','애플린');Object.assign(q,{region:'카르반',city:'애플린',travel,duration:travel*2+180,worldKind:'monster',type:'조사'});mSetup13(q,m13(36),'관찰')}else if(q.name==='외곽 몬스터 토벌'){mSetup13(q,m13(12),'퇴치');q.region='파르디아 도시 연합';q.city='벨로른';q.travel=30;q.worldKind='monster';q.duration=240;q.reward=1000}}}
