function monsterArt465(m,detail=false){return `<img class="monster-art465 ${detail?'monster-detail465':''}" src="assets/monsters/${String(m.id).padStart(2,'0')}.webp" alt="${esc(m.name)}" ${detail?'':'loading="lazy"'}>`}
