function mPanel13(){let m=m13(mSelected13),r=mRules13[m.id],rs=mRegions13(m);let region=rs.find(x=>x.name===mRegion13)||rs[0];let cities=region?.cities.filter(c=>!worldLocked(c.name))||[];let seen=state.monster13.seen[m.id];return `<h2>몬스터 의뢰 · 현장 기록</h2><div class="card"><small>도감 80종 · 현장 기록 ${Object.values(state.monster13.seen).filter(x=>x.encounters>0).length}종</small><label>검색<input id="m-search13" value="${esc(mFilter13)}" oninput="mSearch13(this.value)" placeholder="이름 · 서식지 · 특징"></label><label>등급<select onchange="mGradeSet13(this.value)">${['전체',...Object.keys(mGrade13)].map(g=>`<option ${g===mGradeFilter13?'selected':''}>${esc(g)}</option>`).join('')}</select></label><div id="m-list13" class="m-list13">${mList13()}</div></div><div class="card"><div class="row"><h3>${esc(m.name)}</h3><b>${esc(m.등급)}</b></div>${monsterArt465(m,true)}<p>${esc(m['능력·특징'])}</p><small>기록 서식지: ${esc(m.서식지)}</small><p>도감 대응: ${esc(m['취약점'])}</p><p>게임 전투 효과: ${esc(r[4])} · 권장 능력치 ${r[1]}</p><small>게임용 수치: 위협 ${r[2]} · 방어 ${r[3]} · 기록 ${seen?.encounters||0}회</small>${region?`<label>원정 연락 거점<select onchange="mRegion13=this.value;render()">${rs.map(x=>`<option ${region===x?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>도시<select id="m-city13">${cities.map(c=>`<option>${esc(c.name)}</option>`).join('')}</select></label><small>도시는 연락 거점이며 정확한 개체 출현 지점은 미확정입니다.</small>${mModes13(m).map(mode=>`<button class="wide primary" onclick="mOffer13(${m.id},'${mode}')">${mode==='관찰'?'관찰·위험 조사':'퇴치 의뢰 등록'} · 난도 ${mode==='관찰'?Math.max(16,Math.round(mGrade13[m.등급]*.62)):mGrade13[m.등급]}</button>`).join('')}`:'<p class="muted">국가별 서식지가 미확정되어 원정 등록 불가. 문헌 조사로 대응법을 기록할 수 있습니다.</p><button class="wide" onclick="mOffer13('+m.id+',&quot;문헌&quot;)">문헌 조사 · 1시간</button>'}</div><h3>최근 현장 기록</h3>${state.monster13.reports.slice(0,12).map(x=>`<details class="card"><summary>${esc(m13(x.id)?.name||'미확인')} · ${esc(x.mode)} · ${x.ok?'완료':'미완료'}</summary><small>${esc(x.city)} · ${date(x.time)}</small>${x.lines.map(l=>`<p>${esc(l)}</p>`).join('')}</details>`).join('')||'<p class="muted">아직 기록이 없습니다.</p>'}`}
function mOffer13(id,mode){let m=m13(id);if(!m||state.dialogue)return;let rs=mRegions13(m);if(mode==='문헌'){if(rs.length)return;let q={monsterId:id,monsterMode:'문헌',monsterTurns:['문헌 대조 · '+m['능력·특징'],'도감 대응 · '+m['취약점']]};let rec=state.monster13.seen[id];if(rec?.literature)return;mRecord13(q,true);state.monster13.seen[id].literature=true;log(m.name+' 문헌 조사 완료. 실제 조우 아님.');advance(60);return}if(!mModes13(m).includes(mode))return;let r=rs.find(x=>x.name===mRegion13)||rs[0],c=r?.cities.find(c=>c.name===$('#m-city13')?.value&&!worldLocked(c.name));if(!c)return;let key='monster:'+id+':'+mode+':'+c.name;let day=Math.floor(state.time/1440);if(state.world.offers[key]===day||state.quests.some(q=>q.worldOffer===key&&['open',...liveStatuses].includes(q.status))){notice='이미 등록한 의뢰입니다.';render();return}let travel=routeMinutes(r.name,c.name),grade=mGrade13[m.등급];let q={id:++state.serial,name:m.name+' · '+mode,type:mode==='관찰'?'조사':'퇴치',reward:Math.round(grade*(mode==='관찰'?14:25)),duration:travel*2+(mode==='관찰'?120:240),difficulty:grade,status:'open',party:[],report:[],region:r.name,city:c.name,travel,worldKind:'monster',worldOffer:key,offerDay:day};mSetup13(q,m,mode);state.world.offers[key]=day;state.quests.push(q);screen='의뢰';selectedQuest=q.id;save();render()}
const encounter12m=encounter;encounter=function(q){let m=m13(q.monsterId);if(!m)return encounter12m(q);if(q.city)worldVisit(q);let ps=team(q),[pattern,stat,pressure,guard,desc]=mRules13[m.id],observe=q.monsterMode==='관찰';if(!ps.length){q.outcome='failed';q.stage='귀환';return}let average=ps.reduce((sum,p)=>sum+(p.stats[stat]||0),0)/ps.length,prep=(q.prep||0)*8+(q.staffSurvey?6:0),counter=average+prep>=55;let base=power(ps)+teamBond(ps)+prep;let threat=q.difficulty+(observe?0:guard);if(pattern==='magic')base-=ps.reduce((sum,p)=>sum+gearBonus(p,'power')*.15+(p.stats.마법||0)*.12,0);if(pattern==='pack')threat+=ps.length===1?12:3;if(pattern==='regen'&&!counter&&!observe)threat+=20;if(pattern==='armor'&&counter)threat-=guard*.6;if(counter)base+=8;let risk=pressure*(counter?.55:1)*(observe?.55:1);mLog13(q,`${m.name} · ${desc} · ${stat} ${Math.round(average)} · ${counter?'대응 성공':'대응 부족'}`);mLog13(q,'도감 대응: '+m['취약점']);let retreat=q.policy==='safe'&&(base<threat*.80||ps.some(p=>p.hp<=q.threshold));if(retreat){q.outcome='failed';q.stage='귀환';mLog13(q,'위험 평가 후 교전 없이 철수.');mRecord13(q,false);return}let progress=0,lost=[];for(let turn=1;turn<=3;turn++){let score=base*(1-(turn-1)*.05);if(!counter&&['illusion','shadow','wind'].includes(pattern))score-=pressure*.5;if(pattern==='regen'&&!counter&&!observe&&turn>1)score-=pressure*.4;let chance=clamp(.55+(score-threat)/160,.08,.97);let pass=Math.random()<chance;if(pass)progress++;mLog13(q,`현장 ${turn}단계 · ${pass?(observe?'관찰 기록 확보':'대응 성공'):'위협 노출'} · ${desc}`);for(let p of ps){if(lost.includes(p.id))continue;p.fatigue=clamp(p.fatigue+(['sleep','ice','bind'].includes(pattern)?5:2)+Math.ceil(risk/9),0,100);if(!observe)wear(p,rand(1,4));let hit=pattern==='peace'?0:clamp((pass?.06:.27)+risk/100-(q.prep||0)*.05,.01,.75);if(Math.random()<hit){let dmg=Math.max(1,Math.round(rand(3,9)+risk*.7+(!counter&&['poison','fire','shock'].includes(pattern)?3:0)-gearBonus(p,'guard')));if(p.kit){dmg=Math.ceil(dmg*.65);p.kit=0}let sev=injure(p,dmg,desc+' · 부상');if(p.hp>0&&p.hp<=45&&p.bag.potion>0){p.bag.potion--;p.hp=Math.min(100,p.hp+25);mLog13(q,p.name+' · 회복약 사용')}mLog13(q,p.name+' · 건강 '+Math.round(p.hp)+'%');if(p.hp<=15&&sev===3){lost.push(p.id);p.status='귀환 지연'}}}if(lost.length||q.policy==='safe'&&ps.some(p=>p.hp<=q.threshold)){mLog13(q,'건강 악화로 현장 활동 중단.');break}}q.outcome=progress>=2&&!lost.length?'success':'failed';q.stage='귀환';if(lost.length){q.lost=lost;q.status='delayed';q.checkAt=q.end+120;q.deadline=q.end+720+(q.travel||0);q.stage='귀환 지연';mLog13(q,'미귀환 인원 발생. 기존 구조 체계로 전환.')}mRecord13(q,q.outcome==='success');};
const loot12m=collectLoot;collectLoot=function(q){let m=m13(q.monsterId);if(!m)return loot12m(q);if(q.lootRecorded)return;q.lootRecorded=true;q.loot={};if(q.monsterMode!=='퇴치'){issue(q,'관찰 의뢰 · 생태 기록만 회수.');return}let key='spec'+m.id,n=Math.min(mGrade13[m.등급]>=77?2:1,Math.max(0,storageLimit()-storageUsed()));if(n){state.inventory.goods[key]=(state.inventory.goods[key]||0)+n;q.loot[key]=n;issue(q,goods[key].name+' '+n+'개 · '+m['채집 소재']+' (감정용)')}else issue(q,'창고 공간 부족으로 표본 미회수.');};
const mission12m=missionCard;missionCard=function(q){let h=mission12m(q),m=m13(q.monsterId);return m?h.replace('</summary>','</summary><p class="muted">'+esc(m.name)+' · '+esc(m.등급)+' · '+esc(mRules13[m.id][4])+'</p>'):h};
const render12m=render;render=function(){render12m();if(!state)return;let main=$('main');if(screen==='몬스터'){main.innerHTML=mPanel13();$('nav button:nth-child(3)')?.classList.add('active');$('nav button:nth-child(5)')?.classList.remove('active')}else if(screen==='의뢰'){main.insertAdjacentHTML('afterbegin','<button class="wide primary" onclick="mOpen13()">몬스터 의뢰 · 80종 생태 조사</button>');for(let q of state.quests.filter(q=>q.status==='open'&&q.monsterId)){let b=main.querySelector(`[onclick="dispatch(${q.id})"],[onclick="selectedQuest=${q.id};render()"]`);if(b){let m=m13(q.monsterId),r=mRules13[m.id];b.closest('.card')?.querySelector('h3')?.insertAdjacentHTML('afterend',`<div class="m-info13"><b>${esc(m.name)} · ${esc(m.등급)}</b><small>${esc(r[4])} · 권장 ${r[1]} · ${esc(q.monsterMode)}</small></div>`)}}}else if(screen==='역사'&&historyTab==='몬스터 도감'){main.insertAdjacentHTML('afterbegin','<button class="wide primary" onclick="mOpen13()">도감 기반 현장 의뢰 등록</button>')}};


// v1.4: generated citizen contracts, linked commissions and seasonal incidents.
// All new clients and incidents are game-only, not official lore.
const {citizen:citizen14,seasons:seasons14,chains:chains14,incidents:incident14}=window.__gameData['citizen-events'];
let boardFilter14='전체';
const season14=()=>Math.floor(Math.floor(state.time/1440)%120/30);
const day14=()=>Math.floor(state.time/1440);
const norm13q=normalize;normalize=function(s=state){s=norm13q(s);if(!s)return s;s.contract14??={lastDay:-1,incidents:[],pending:null,seen:{},history:[]};let v=s.contract14;v.incidents??=[];v.seen??={};v.history??=[];v.lastDay??=-1;return s};
function qRecord14(text){state.contract14.history.unshift({time:state.time,text});state.contract14.history=state.contract14.history.slice(0,120);log(text)}
function qCreate14(t,kind='시민',parent=null){let day=day14(),reward=kind==='연속'||kind==='긴급'?t[5]:Math.round(t[5]*rand(90,115)/100);let q={id:++state.serial,name:t[0],type:t[1],reward,duration:t[6],difficulty:t[7],status:'open',party:[],report:[],citizen14:{kind,client:t[2],story:t[3],goal:t[4],day,expires:day+(kind==='긴급'?2:kind==='연속'?5:rand(2,4)),chain:t[8]||null,parent:parent?.id||null}};state.quests.push(q);return q}
function expire14(){let day=day14();for(let q of state.quests){if(q.status==='open'&&q.citizen14&&day>=q.citizen14.expires){q.status='expired';q.finished=state.time;qRecord14(q.name+' · 접수 기한 만료');if(selectedQuest===q.id)selectedQuest=null;}}}
function populate14(){let v=state.contract14,day=day14();if(v.lastDay===day)return;v.lastDay=day;expire14();let pool=[...citizen14,...seasons14[season14()]],n=Math.min(rand(4,7),Math.max(0,12-state.quests.filter(q=>q.status==='open'&&q.citizen14&&['시민','계절'].includes(q.citizen14.kind)).length));for(let i=0;i<n;i++){let eligible=pool.filter(t=>!state.quests.some(q=>q.name===t[0]&&['open',...liveStatuses].includes(q.status)));if(!eligible.length)break;let seasonal=eligible.filter(t=>seasons14[season14()].includes(t));let t=pick(i===0&&seasonal.length?seasonal:eligible);qCreate14(t,seasons14[season14()].includes(t)?'계절':'시민');} }
const add13q=addQuests;addQuests=function(){add13q();populate14()};
// Imported saves receive the new board immediately, without advancing time.
const render13q=render;render=function(){if(state){normalize();if(state.contract14.lastDay!==day14()){populate14();save()}}render13q();if(!state||state.dialogue)return;let main=$('main');if(screen==='시민 사건'){main.innerHTML=incidentPanel14();$('nav button:nth-child(3)')?.classList.add('active');}else if(screen==='의뢰'){let focused=state.quests.find(q=>q.id===selectedQuest&&q.status==='open');if(focused&&boardFilter14!=='전체'&&boardFilter14!==(focused.citizen14?.kind||'기존 의뢰'))boardFilter14='전체';main.insertAdjacentHTML('afterbegin',`<div class="card"><div class="row"><b>시민 의뢰 게시판</b><small>오늘 ${state.quests.filter(q=>q.citizen14?.day===day14()).length}건 접수</small></div><button class="wide ${state.contract14.pending?'primary':''}" onclick="go('시민 사건')">${state.contract14.pending?'새 시민 사건 확인':'시민 사건 · 기록'}</button><label>의뢰 종류<select onchange="filter14(this.value)">${['전체','시민','계절','연속','긴급','기존 의뢰'].map(t=>`<option ${t===boardFilter14?'selected':''}>${t}</option>`).join('')}</select></label></div>`);for(let q of state.quests.filter(q=>q.status==='open')){let btn=main.querySelector(`[onclick="dispatch(${q.id})"],[onclick="selectedQuest=${q.id};render()"]`),card=btn?.closest('.card');if(!card)continue;card.dataset.contract14=q.citizen14?.kind||'기존 의뢰';if(q.citizen14){let c=q.citizen14;card.querySelector('h3')?.insertAdjacentHTML('afterend',`<div class="citizen14"><small>${esc(c.kind)} · 의뢰인: ${esc(c.client)} · 접수 ${Math.max(0,c.expires-day14())}일 남음</small><p>${esc(c.story)}</p><small>목표: ${esc(c.goal)}</small>${c.parent?'<small>이전 의뢰의 후속 요청</small>':''}</div>`);}}filter14(boardFilter14);}else if(screen==='길드'){let box=document.createElement('div');box.className='card';box.innerHTML=`<div class="row"><b>시민의 소식</b><small>${state.contract14.pending?'새 사건':'의뢰와 계절'}</small></div><button class="wide ${state.contract14.pending?'primary':''}" onclick="go('시민 사건')">시민 사건 확인 →</button>`;main.querySelector('.quick-grid')?.after(box);}};
function filter14(v){boardFilter14=v;document.querySelectorAll('[data-contract14]').forEach(e=>{e.hidden=v!=='전체'&&e.dataset.contract14!==v})}
const dispatch13q=dispatch;dispatch=function(id){let q=state.quests.find(q=>q.id===id);if(q?.citizen14&&q.status==='open'&&day14()>=q.citizen14.expires){expire14();save();render();return}dispatch13q(id)};
const finish13q=finish;finish=function(q){let before=q.status;finish13q(q);if(!q.citizen14||q.citizen14.settled||!['success','failed'].includes(q.status)||['success','failed'].includes(before))return;let c=q.citizen14;c.settled=true;if(q.status==='success'){qRecord14(q.name+' · '+c.client+'의 의뢰 완료');if(c.chain&&chains14[c.chain]){let next=qCreate14(chains14[c.chain],'연속',q);qRecord14('후속 의뢰 접수: '+next.name);}}else qRecord14(q.name+' · 시민 의뢰 미완료');};
const mission13q=missionCard;missionCard=function(q){let html=mission13q(q);return q.citizen14?html.replace('</summary>',`</summary><p class="muted">${esc(q.citizen14.kind)} · ${esc(q.citizen14.client)} · ${esc(q.citizen14.goal)}</p>`):html};
function incidentReady14(o){return state.fund>=(o.cost||0)&&state.food+(o.food||0)>=0}
function incidentDay14(){let v=state.contract14,day=day14();if(v.pending&&day>=v.pending.expires){qRecord14('사건 기한 종료: '+(incident14.find(e=>e.id===v.pending.id)?.title||'시민 사건'));v.pending=null;}if(v.pending||day-(v.lastIncident??-99)<2||Math.random()>.7)return;let pool=incident14.filter(e=>(e.season===undefined||e.season===season14())&&day-(v.seen[e.id]??-99)>=10);if(!pool.length)return;let e=pick(pool);v.pending={id:e.id,day,expires:day+(e.urgent?2:3)};v.lastIncident=day;v.seen[e.id]=day;qRecord14('시민 사건 접수: '+e.title);if(e.urgent&&!interrupt){interrupt=true;notice='긴급 시민 사건: '+e.title;screen='시민 사건';selectedQuest=null;}}
const daily13q=dailyStory;dailyStory=function(){daily13q();incidentDay14()};
function incidentChoose14(id,i){if(state.dialogue)return;let v=state.contract14,p=v.pending,e=incident14.find(x=>x.id===id),o=e?.opts[i];if(!p||p.id!==id||day14()>=p.expires||!o||!incidentReady14(o))return;if(o.cost&&!cash(-o.cost,'시민 지원',e.title))return;state.food+=o.food||0;state.rep=clamp(state.rep+(o.rep||0),0,100);for(let p of state.economy.staff.slice(1)){p.morale=clamp(p.morale+(o.morale||0),0,100);p.fatigue=clamp(p.fatigue+(o.fatigue||0),0,100)}let q=o.quest?qCreate14(o.quest,e.urgent?'긴급':'시민'):null;v.pending=null;v.incidents.unshift({time:state.time,id,title:e.title,choice:o.label,quest:q?.id||null});v.incidents=v.incidents.slice(0,100);qRecord14(e.title+' · '+o.label);notice=q?'신규 의뢰가 접수되었습니다.':'시민 사건에 대응했습니다.';save();if(q){screen='의뢰';boardFilter14='전체';selectedQuest=q.id}render()}
function incidentPanel14(){let v=state.contract14,p=v.pending,e=incident14.find(x=>x.id===p?.id);return `<h2>시민 사건 · 계절 소식</h2><p class="muted">게임 전용 사건 · ${['봄','여름','가을','겨울'][season14()]} · 시간이 흐르면 새로운 의뢰와 사건이 접수됩니다.</p>${e?`<div class="card ${e.urgent?'urgent':''}"><small>${e.urgent?'긴급 경보':'시민 소식'} · ${p.expires-day14()}일 남음</small><h3>${esc(e.title)}</h3><p>${esc(e.text)}</p>${e.opts.map((o,i)=>`<button class="wide" onclick="incidentChoose14('${e.id}',${i})" ${incidentReady14(o)?'':'disabled'}>${esc(o.label)}</button>`).join('')}</div>`:'<div class="card">현재 대응할 사건이 없습니다.</div>'}<button class="wide primary" onclick="boardFilter14='전체';go('의뢰')">의뢰 게시판으로</button><h3>대응 기록</h3>${v.incidents.slice(0,15).map(x=>`<div class="card"><small>${date(x.time)}</small><b>${esc(x.title)}</b><p>${esc(x.choice)}</p>${x.quest?`<small>후속 의뢰: ${esc(questStatus(state.quests.find(q=>q.id===x.quest)||{}))}</small>`:''}</div>`).join('')||'<p class="muted">아직 대응 기록이 없습니다.</p>'}<h3>시민 의뢰 연대기</h3>${v.history.slice(0,20).map(x=>`<div class="log"><small>${date(x.time)}</small><br>${esc(x.text)}</div>`).join('')||'<p class="muted">아직 기록이 없습니다.</p>'}`}


// v1.5: autonomous life events, using the existing 120-day calendar.
const lifeDay15=(s=state)=>Math.floor(s.time/1440);
const adult15=p=>p?.generated===true&&Number.isFinite(p.profile?.age)&&p.profile.age>=18;
const lifeNormalize14=normalize;normalize=function(s=state){s=lifeNormalize14(s);if(!s)return s;s.life15??={lastDay:lifeDay15(s),events:[],families:{},nextChild:1};for(let p of [...s.people,...s.applicants])if(adult15(p)){p.life15??={birthday:((lifeDay15(s)+1+(p.id*37)%119)%120),lastBirthday:lifeDay15(s),retireAge:65+(p.id%6),familyWish:p.id%5!==0};}return s};
function lifeLog15(text,ids=[]){state.life15.events.unshift({time:state.time,text,ids});state.life15.events=state.life15.events.slice(0,250);socialEvent(text,ids)}
const member14life=currentMember;currentMember=function(p){return member14life(p)&&p.status!=='은퇴'};
const label14life=bondLabel;bondLabel=function(r){return r.romance==='배우자'?'배우자':r.romance==='사별'?'사별':r.romance==='이혼'?'이혼':label14life(r)};
const partner14life=partnered;partnered=function(p,except){return partner14life(p,except)||Object.values(state.social.pairs).some(r=>r!==except&&['연인','배우자'].includes(r.romance)&&(r.a===p.id||r.b===p.id)&&state.people.some(x=>x.id===(r.a===p.id?r.b:r.a)&&x.status!=='사망'))};
const bond14life=changeBond;changeBond=function(a,b,delta,trust,why,shared=false){let before=relation(a,b).romance;let r=bond14life(a,b,delta,trust,why,shared);if(!r||!adult15(a)||!adult15(b))return r;let day=lifeDay15();if(before!=='연인'&&r.romance==='연인'){r.loveDay=day;lifeLog15(a.name+'과(와) '+b.name+'은 서로에게 마음을 고백하고 교제를 시작했다.',[a.id,b.id])}if(before==='연인'&&r.romance==='이별')lifeLog15(a.name+'과(와) '+b.name+'의 교제가 끝났다.',[a.id,b.id]);return r};
function family15(r){let key=r.a+':'+r.b;return state.life15.families[key]??=( {parents:[r.a,r.b],children:[],pending:null,formed:lifeDay15(),lastPlan:-999} )}
function familyName15(f){return f.parents.map(id=>state.people.find(p=>p.id===id)?.name||'기록 없음').join(' · ')}
function child15(f,route){let id=state.life15.nextChild++,name=pick(['아린','리오','엘라','노아','미아','레아','루안','이안','리나','세온','유나','엘린']);f.children.push({id,name,route,born:lifeDay15(),initialAge:route==='입양'?rand(1,6):0});lifeLog15(familyName15(f)+' 가족에 '+name+'이(가) '+(route==='입양'?'입양으로 함께하게 되었다.':'태어났다.'),f.parents)}
function dailyLife15(){let day=lifeDay15(),v=state.life15;if(v.lastDay===day)return;v.lastDay=day;for(let p of state.people.filter(adult15)){let l=p.life15;if(!l||p.status==='사망')continue;if(day%120===l.birthday&&day>l.lastBirthday){p.profile.age++;l.lastBirthday=day;lifeLog15(p.name+'의 생일 · '+p.profile.age+'세.',[p.id])}if(currentMember(p)&&p.profile.age>=l.retireAge&&p.status==='대기'&&!p.arrears){p.status='은퇴';l.retired=day;state.social.former.push({id:p.id,name:p.name,time:state.time,reason:'은퇴',wallet:p.wallet});lifeLog15(p.name+'이(가) 모험가 생활을 마치고 은퇴했다.',[p.id]);}}
for(let r of Object.values(state.social.pairs)){let a=state.people.find(p=>p.id===r.a),b=state.people.find(p=>p.id===r.b);if(!adult15(a)||!adult15(b))continue;let bothAlive=a.status!=='사망'&&b.status!=='사망',local=a.status==='대기'&&b.status==='대기';if(!bothAlive){if(['연인','배우자'].includes(r.romance)){r.romance='사별';let f=state.life15.families[r.a+':'+r.b];if(f?.pending){f.pending=null;lifeLog15('사별로 인해 진행 중인 가족 계획을 종료했다.',f.parents)}lifeLog15(a.name+'과(와) '+b.name+'의 관계가 사별로 기록되었다.',[a.id,b.id])}continue}if(r.romance==='연인'){r.loveDay??=day;if(local&&day-r.loveDay>=20&&r.affinity>=85&&r.trust>=80&&Math.random()<.12){r.romance='배우자';r.marriedDay=day;family15(r);lifeLog15(a.name+'과(와) '+b.name+'은 서로의 뜻을 확인하고 결혼했다.',[a.id,b.id])}}else if(r.romance==='배우자'){let f=family15(r);if(r.affinity<-20&&r.trust<20&&local){r.romance='이혼';if(f.pending){f.pending=null;lifeLog15('가족 계획이 취소되었다.',f.parents)}lifeLog15(a.name+'과(와) '+b.name+'은 이혼했다. 기존 가족 기록은 보존된다.',f.parents);continue}if(f.pending&&day>=f.pending.due){child15(f,f.pending.route);f.pending=null;f.lastPlan=day}if(local&&!f.pending&&f.children.length<3&&a.life15.familyWish&&b.life15.familyWish&&day-(r.marriedDay??f.formed)>=20&&day-f.lastPlan>=60&&r.affinity>=80&&r.trust>=75&&Math.random()<.035){let birth=a.profile.gender!==b.profile.gender&&a.profile.age<=45&&b.profile.age<=45&&Math.random()<.5;f.pending={route:birth?'출산':'입양',due:day+(birth?90:20)};f.lastPlan=day;lifeLog15(familyName15(f)+'은 서로 합의하여 '+f.pending.route+'을(를) 준비하기로 했다.',f.parents)}}}}
const daily14life=dailySocial;dailySocial=function(){daily14life();dailyLife15()};
function lifePanel15(){let v=state.life15,ps=state.people.filter(adult15),families=Object.values(v.families);return `<h2>삶과 가족</h2><p class="muted">게임 전용 생애 기록 · 1년 120일. 가족 형성은 인물의 자율적인 선택이며 공식 인물에게 적용되지 않습니다.</p><div class="grid"><div class="card"><small>가족</small><div class="value">${families.length}</div></div><div class="card"><small>은퇴</small><div class="value">${ps.filter(p=>p.status==='은퇴').length}</div></div></div><h3>모험가 생애</h3>${ps.map(p=>`<div class="card"><b>${esc(p.name)}</b> · ${p.profile.age}세 <small>${esc(p.status)}</small><p>생일: ${['봄','여름','가을','겨울'][Math.floor(p.life15.birthday/30)]} ${p.life15.birthday%30+1}일 · 은퇴 희망 ${p.life15.retireAge}세</p><small>${p.life15.familyWish?'가족 형성을 희망함':'자녀 계획을 원하지 않음'}</small></div>`).join('')||'<p class="muted">랜덤 모험가를 영입하면 생애 기록이 시작됩니다.</p>'}<h3>가족 수첩</h3>${families.map(f=>`<div class="card"><b>${esc(familyName15(f))}</b><p>${esc(state.social.pairs[f.parents.join(':')]?.romance||'가족 기록')}</p>${f.pending?`<p>가족 계획: ${esc(f.pending.route)} · ${Math.max(0,f.pending.due-lifeDay15())}일 남음</p>`:''}${f.children.map(c=>`<div class="log">${esc(c.name)} · ${c.initialAge+Math.max(0,Math.floor((lifeDay15()-c.born)/120))}세 · ${esc(c.route)}<br><small>가족 기록 · 전투 및 모집 대상 아님</small></div>`).join('')||'<small>자녀 기록 없음</small>'}</div>`).join('')||'<p class="muted">아직 형성된 가족이 없습니다.</p>'}<h3>생애 기록</h3>${v.events.slice(0,50).map(e=>`<div class="log"><small>${date(e.time)}</small><br>${esc(e.text)}</div>`).join('')||'<p class="muted">아직 기록이 없습니다.</p>'}`}
const profile14life=profile;profile=function(p){let h=profile14life(p);return adult15(p)&&p.life15?h+`<div class="card"><h3>생애 기록</h3><p>생일: ${['봄','여름','가을','겨울'][Math.floor(p.life15.birthday/30)]} ${p.life15.birthday%30+1}일 · 은퇴 희망 ${p.life15.retireAge}세</p><button class="wide" onclick="go('생애')">가족 및 생애 수첩</button></div>`:h};
const render14life=render;render=function(){render14life();if(!state||state.dialogue)return;let m=$('main');if(screen==='생애'){m.innerHTML=lifePanel15();$('nav button:nth-child(2)')?.classList.add('active')}else if(screen==='관계'||screen==='길드'){m.insertAdjacentHTML('afterbegin','<button class="wide" onclick="go(\'생애\')">삶과 가족 · 생일 · 은퇴 기록</button>')}};


// v1.6: optional hero stories, independent of the original ending requirements.
const heroStories16=[
['luna','루나','bestiary',22,'기억을 남기는 이유','오래된 기록의 사본을 정리해 줄래? 이름 없는 사람들의 기록도 사라지지 않았으면 해.','카르코의 도감과 현장 보고 대조','벨로른','도감의 관찰 기록을 정리했어. 누군가 무사히 돌아오는 데 도움이 되겠지.','후대에 남길 안전 기록 정리','기록은 누군가의 삶을 기억하는 방법이야. 고마워.'],
['kael','카엘 아르벨라제','apple',26,'자신의 이름으로','애플린의 생활 기록을 조사해 주시겠습니까? 영웅의 이름 뒤에 살아가는 사람들의 이야기도 궁금합니다.','애플린 생활 기록 조사','애플린','보고서를 읽었습니다. 과거를 존중하되 지금의 사람들을 잊지 않겠습니다.','애플린 주민의 생활 요청 정리','제가 해야 할 일은 제 스스로 선택하겠습니다. 협력해 주셔서 감사합니다.'],
['ren','렌 피츠','bestiary',30,'그림으로 읽는 길','글만 빼곡하면 알아보기 어렵잖아. 위험한 몬스터를 그림으로 구분할 수 있게 해 봐.','그림 도감의 위험 표시 정리','벨로른','이 정도면 글을 못 읽어도 알아볼 수 있겠네.','현장 그림 안내서 검토','쓸 만하네. 다음에 모르는 게 있으면 이걸 보면 되겠다.'],
['asha','아샤 베르디아','dynasty',34,'왕관의 책임','왕국의 사람들에게 필요한 물자가 무엇인지 조사해 주세요. 안전을 우선으로 부탁합니다.','아라냐 생활 물자 수요 조사','아라냐','주민들의 상황을 살피는 일이 우선이지요. 보고서 감사합니다.','구호 물자 전달 경로 검토','사람들을 위한 판단을 계속해 주세요.'],
['sera','세라 라우렌','porca',36,'돌아온 사람들을 위하여','다친 모험가들이 충분히 쉬고 있는지 살펴봐 주세요. 회복을 서두르지 않았으면 좋겠어요.','회복 지원 자료 조사','벨로른','부상뿐 아니라 피로도 살펴야 해요.','귀환자 휴식 안내 정리','다들 무사히 돌아와서 다행이에요. 고마워요.'],
['kai','카이 아르벨라제','magic',38,'마법과 한계','마법의 원리를 연구하는 것과 몸이 그 힘을 견디는 것은 다른 문제예요. 안전한 연구 자료를 모아 주세요.','마법 연구 문헌 비교','벨로른','무리한 실험 없이 자료를 비교했군요.','마력 사용 안전 수칙 검토','힘을 사용할 수 있다는 것이 언제나 사용해야 한다는 뜻은 아니니까요.'],
['sion','시온 라우렌','porca',40,'느긋한 귀환','서두르다가 다치면 치료하는 사람만 힘들어지잖아. 귀환 준비를 한번 살펴봐.','귀환자 지원 절차 조사','벨로른','제법 꼼꼼하네. 그래도 쉴 때는 쉬어야지.','구조 연락망 점검','좋아. 이번에는 무리하지 말고 돌아오라고.'],
['eileen','에일린 발렌시아','luna',48,'남겨진 기억','오래된 기록을 읽다 보면 그때의 사람들을 떠올리게 돼. 자료를 함부로 단정하지 말고 살펴봐 줘.','500년 전 기록의 출처 대조','벨로른','기록마다 관점이 다를 수 있어.','상충하는 기록의 분류','고마워. 기억하는 것과 과거를 되돌리는 건 다른 일이니까.']
].map(([id,name,need,rep,title,opening,q1,city,mid,q2,end])=>({id,name,need,rep,title,opening,q1,city,mid,q2,end}));
const normalize15h=normalize;normalize=function(s=state){s=normalize15h(s);if(s)s.hero16??={tracks:{},records:[]};return s};
function hs16(id){return heroStories16.find(h=>h.id===id)}
function ht16(id){return state.hero16.tracks[id]??={stage:0,choices:[],completed:[]}}
function hReady16(h){return historyUnlocked(h.need)&&state.rep>=h.rep&&(!heroEvents.some(x=>x.id===h.id)||!!state.history.encounters[h.id])}
function hTalk16(id){let h=hs16(id),t=h&&ht16(id);if(!h||!hReady16(h)||state.dialogue||![0,2,4].includes(t.stage))return;dialogueStart({kind:'hero16',hero:id,name:h.name,step:0,asked:[],returnTo:'영웅 이야기',chapter:t.stage})}
const lines15h=linesFor;linesFor=function(d){if(d.kind!=='hero16')return lines15h(d);let h=hs16(d.hero);if(!h)return null;let line=d.chapter===0?h.opening:d.chapter===2?h.mid:h.end;return {g:line,q:[['이야기를 듣고 함께하겠습니다.',d.chapter===4?'함께한 기록을 남겨 주세요.':'부탁할 일을 기록해 두겠습니다.'],['어떤 점을 유의할까요?',d.chapter===4?'기록을 읽는 다음 사람을 생각해 주세요.':'사람의 안전과 기록의 정확성을 먼저 생각해 주세요.']]}};
// Own dialogue controls avoid the generic member memory path.
function hChoose16(i){let d=state.dialogue,t=d&&linesFor(d);if(d?.kind!=='hero16'||d.step!==0||!t.q[i]||d.asked.includes(i))return;d.asked.push(i);d.step=1;d.question=t.q[i][0];d.answer=t.q[i][1];dialogueLog(d,'지아 메르벨',d.question);dialogueLog(d,d.name,d.answer);save();render()}
const panel15h=dialoguePanel;dialoguePanel=function(){let d=state?.dialogue;if(d?.kind!=='hero16')return panel15h();let t=linesFor(d);return `<section class="dialogue card"><div class="eyebrow">영웅 이야기 · 게임 전용</div><div class="dialogue-art">${portrait(d.name)}</div><div class="dialogue-text"><h2>${esc(d.name)}</h2><p>${esc(d.step===1?d.answer:t.g)}</p></div>${d.step===1?'<button class="wide primary" onclick="nextTalk()">다른 질문</button>':t.q.map(([q],i)=>`<button class="wide" onclick="hChoose16(${i})" ${d.asked.includes(i)?'disabled':''}>${esc(q)}</button>`).join('')}<button class="wide primary" onclick="hEnd16()">${d.asked.length?'대화 마치기 · 30분':'돌아가기'}</button></section>`};
function hEnd16(){let d=state.dialogue;if(d?.kind!=='hero16')return;let h=hs16(d.hero),t=ht16(d.hero);state.dialogue=null;screen='영웅 이야기';if(d.asked.length&&t.stage===d.chapter){t.choices.push({chapter:d.chapter,asked:[...d.asked],time:state.time});t.stage++;if(t.stage===5){state.hero16.records.unshift({id:h.id,title:h.title,time:state.time});log(h.name+' · 특별 이야기 완료: '+h.title);state.rep=clamp(state.rep+2,0,100)}save();advance(30)}else{save();render()}}
function hQuest16(id){let h=hs16(id),t=h&&ht16(id);if(!h||!hReady16(h)||state.dialogue||![1,3].includes(t.stage)||state.quests.some(q=>q.hero16===id&&q.heroStage16===t.stage&&['open',...liveStatuses].includes(q.status)))return;let city=h.city,r=historyRegion(city);if(!r||worldLocked(city))return;let travel=routeMinutes(r.name,city);let q={id:++state.serial,name:t.stage===1?h.q1:h.q2,type:'조사',reward:t.stage===1?900:1400,duration:travel*2+120,difficulty:t.stage===1?24:32,status:'open',party:[],report:[],region:r.name,city,travel,worldKind:'hero-story',hero16:id,heroStage16:t.stage};state.quests.push(q);selectedQuest=q.id;screen='의뢰';save();render()}
const finish15h=finish;finish=function(q){let before=q.status;finish15h(q);if(!q.hero16||before==='success'||q.status!=='success')return;let t=ht16(q.hero16);if(t.stage===q.heroStage16){t.completed.push(q.id);t.stage++;log(hs16(q.hero16).name+' · 후속 대화 해금')}};
function heroPanel16(){return `<h2>영웅들의 발자취</h2><p class="muted">게임 전용 특별 이야기 · 공식 인물의 본편 행적이나 관계를 변경하지 않습니다. 기존 엔딩 조건과 별개입니다.</p><div class="card"><b>완료 ${state.hero16.records.length} / ${heroStories16.length}</b></div>`+heroStories16.map(h=>{let t=ht16(h.id),ready=hReady16(h),pending=state.quests.some(q=>q.hero16===h.id&&q.heroStage16===t.stage&&['open',...liveStatuses].includes(q.status));return `<div class="card"><div class="person history-person">${portrait(h.name)}<div><h3>${esc(h.name)}</h3><b>${esc(h.title)}</b><p class="muted">${t.stage===5?'이야기 완료':ready?['첫 만남','첫 의뢰','후속 대화','두 번째 의뢰','마지막 대화'][t.stage]:'평판 '+h.rep+' · 역사 기록 '+esc(historyRecords.find(r=>r.id===h.need)?.title||h.need)+' · 기존 방문 완료(해당 인물)'}</p><small>${t.stage}/5 단계</small></div></div>${ready&&t.stage<5?([0,2,4].includes(t.stage)?`<button class="wide primary" onclick="hTalk16('${h.id}')">대화하기</button>`:`<button class="wide primary" onclick="hQuest16('${h.id}')" ${pending?'disabled':''}>${pending?'의뢰 진행 중':esc(t.stage===1?h.q1:h.q2)+' · 등록'}</button>`):''}</div>`}).join('')+`<h3>완료 기록</h3>${state.hero16.records.map(r=>`<div class="log">${esc(r.title)} · ${date(r.time)}</div>`).join('')||'<p class="muted">아직 완료한 이야기가 없습니다.</p>'}`}
const render15h=render;render=function(){render15h();if(!state||state.dialogue)return;let m=$('main');if(screen==='영웅 이야기'){m.innerHTML=heroPanel16();$('nav button:nth-child(5)')?.classList.add('active')}else if(['역사','길드'].includes(screen)){m.insertAdjacentHTML('afterbegin',`<button class="wide" onclick="go('영웅 이야기')">영웅 특별 이야기 · ${state.hero16.records.length}/8</button>`)}};


// v1.7 — fictional competitors for this game, not official world canon.
