const normalize16r=normalize;normalize=function(s=state){s=normalize16r(s);if(!s)return s;s.rivals17??={day:Math.floor(s.time/1440),guilds:rivals17.map(r=>({id:r.id,score:r.base,relation:50,completed:0,recruits:0})),history:[],offers:[],lastJoint:{},wins:0,joint:0};return s};
function rivalLog17(text){state.rivals17.history.unshift({time:state.time,text});state.rivals17.history=state.rivals17.history.slice(0,100);log(text)}
function rivalScore17(){return Math.round(state.rep*2+state.completed*4+state.people.filter(currentMember).length*5+state.rivals17.wins*5+state.rivals17.joint*3)}
function rank17(){return [{id:'player',name:'길의 등불',score:rivalScore17()},...state.rivals17.guilds.map(g=>({...g,name:rivals17.find(r=>r.id===g.id).name}))].sort((a,b)=>b.score-a.score||a.id.localeCompare(b.id))}
function dailyRivals17(){let v=state.rivals17,day=Math.floor(state.time/1440);if(day<=v.day)return;v.day=day;for(let g of v.guilds){if(Math.random()<.65){g.completed++;g.score+=rand(2,6)}}v.offers=v.offers.filter(o=>state.applicants.some(p=>p.id===o.person));for(let o of [...v.offers])if(o.due<=day){let p=state.applicants.find(p=>p.id===o.person),g=v.guilds.find(x=>x.id===o.guild);if(p&&g){state.applicants=state.applicants.filter(x=>x.id!==p.id);g.recruits++;g.score+=5;rivalLog17(p.name+'이(가) '+rivals17.find(x=>x.id===g.id).name+'의 계약을 선택했다.')}v.offers=v.offers.filter(x=>x!==o)}let pool=state.applicants.filter(p=>p.generated&&!v.offers.some(o=>o.person===p.id));if(pool.length&&Math.random()<.65){let p=pick(pool),g=pick(v.guilds);v.offers.push({person:p.id,guild:g.id,due:day+1});rivalLog17(p.name+'에게 '+rivals17.find(x=>x.id===g.id).name+'도 계약을 제안했다.')}}
const daily16r=dailySocial;dailySocial=function(){daily16r();dailyRivals17()};
const hire16r=hire;hire=function(id){let o=state.rivals17.offers.find(x=>x.person===id);hire16r(id);if(o&&state.people.some(p=>p.id===id)){state.rivals17.offers=state.rivals17.offers.filter(x=>x.person!==id);rivalLog17('영입 경쟁 · 길의 등불과 계약 체결');save();render()}};
const applicant16r=applicant;applicant=function(p){let o=state.rivals17.offers.find(x=>x.person===p.id);return (o?`<div class="card urgent"><b>경쟁 계약 제안</b><p>${esc(p.name)} · ${esc(rivals17.find(x=>x.id===o.guild).name)} · ${Math.max(0,o.due-Math.floor(state.time/1440))}일 남음</p></div>`:'')+applicant16r(p)};
function rivalQuest17(id,mode){let v=state.rivals17,g=v.guilds.find(x=>x.id===id),r=rivals17.find(x=>x.id===id),day=Math.floor(state.time/1440);if(!g||!r||state.dialogue||!['joint','race'].includes(mode)||day-(v.lastJoint[id]??-999)<3||state.quests.some(q=>q.rival17===id&&['open',...liveStatuses].includes(q.status))||mode==='joint'&&g.relation<35)return;let q={id:++state.serial,name:r.name+(mode==='joint'?' · 공동 안전 조사':' · 경쟁 운송 의뢰'),type:mode==='joint'?'조사':'운반',reward:mode==='joint'?1000:1500,duration:mode==='joint'?240:180,difficulty:mode==='joint'?30:36,status:'open',party:[],report:[],rival17:id,rivalMode17:mode};v.lastJoint[id]=day;state.quests.push(q);screen='의뢰';selectedQuest=q.id;save();render()}
const finish16r=finish;finish=function(q){let done=['success','failed'].includes(q.status);if(done&&q.rival17&&q.rivalSettled17)return;finish16r(q);if(!q.rival17||q.rivalSettled17||!['success','failed'].includes(q.status))return;let g=state.rivals17.guilds.find(x=>x.id===q.rival17);if(!g)return;q.rivalSettled17=true;let ok=q.status==='success';if(q.rivalMode17==='joint'){g.relation=clamp(g.relation+(ok?10:-4),0,100);if(ok){state.rivals17.joint++;g.score+=3}}else if(ok){state.rivals17.wins++;g.relation=clamp(g.relation-2,0,100)}else{g.score+=5;g.completed++}rivalLog17(q.name+' · '+(ok?'성공':'실패'));};
function rivalPanel17(){let v=state.rivals17,day=Math.floor(state.time/1440);return `<h2>길드 연합 · 경쟁</h2><p class="muted">벨로른 지역 게임 전용 길드 순위 · 평판, 완료 의뢰, 현역 인원 및 협력 실적 기준. 실제 세계관 공식 길드가 아닙니다.</p><div class="card"><h3>길드 순위</h3>${rank17().map((r,i)=>`<div class="row"><b>${i+1}위 · ${esc(r.name)}</b><span>${r.score}점</span></div>`).join('')}<small>경쟁 승리 ${v.wins} · 공동 의뢰 성공 ${v.joint}</small></div><h3>다른 길드</h3>${v.guilds.map(g=>{let r=rivals17.find(x=>x.id===g.id),blocked=day-(v.lastJoint[g.id]??-999)<3||state.quests.some(q=>q.rival17===g.id&&['open',...liveStatuses].includes(q.status));return `<div class="card"><h3>${esc(r.name)}</h3><p>${esc(r.focus)} · 관계 ${g.relation}/100</p><div class="bar"><b style="width:${g.relation}%"></b></div><small>완료 의뢰 ${g.completed} · 영입 ${g.recruits}</small><button class="wide" onclick="rivalQuest17('${g.id}','joint')" ${blocked||g.relation<35?'disabled':''}>공동 안전 조사 등록</button><button class="wide" onclick="rivalQuest17('${g.id}','race')" ${blocked?'disabled':''}>경쟁 운송 의뢰 등록</button><small>${blocked?'진행 중 또는 3일 재등록 제한':'파견은 기존 의뢰 화면에서 진행'}</small></div>`}).join('')}<h3>영입 경쟁</h3>${v.offers.map(o=>{let p=state.applicants.find(x=>x.id===o.person);return p?`<div class="card">${esc(p.name)} · ${esc(rivals17.find(x=>x.id===o.guild).name)}<br><small>${Math.max(0,o.due-day)}일 남음</small></div>`:''}).join('')||'<p class="muted">현재 경쟁 제안 없음</p>'}<button class="wide" onclick="go('모험가')">모험가 모집 화면</button><h3>경쟁 기록</h3>${v.history.map(x=>`<div class="log"><small>${date(x.time)}</small><br>${esc(x.text)}</div>`).join('')||'<p class="muted">기록 없음</p>'}`}
