// v1.8 — local economy, regional quotes and fictional credit contracts.
const levels18={easy:{name:'여유',risk:.85,rate:2},normal:{name:'표준',risk:1,rate:3},hard:{name:'도전',risk:1.18,rate:5}};
const norm17e=normalize;normalize=function(s=state){s=norm17e(s);if(!s)return s;s.market18??={day:Math.floor(s.time/1440),index:100,level:'normal',demand:{},prices:{},regions:{},history:[],loans:[],next:1,crisis:0};return s};
function price18(d){let m=state?.market18;return Math.max(1,Math.round(d.price*(m?.index??100)/100*(m?.prices[d.name]??100)/100))}
function foodPrice18(){return Math.round(100*(state.market18.index/100)*(state.market18.prices['식량']??100)/100)}
function tradePrice18(r,k,mode){let m=state.market18;return Math.max(1,Math.round(price18(goods[k])*(m.regions[r]??100)/100*(mode==='buy'?.72:1.12)))}
function marketDemand18(d,n){let m=state.market18;m.demand[d.name]=clamp((m.demand[d.name]||0)+n,-20,20)}
function debt18(){return state.market18.loans.reduce((a,l)=>a+l.balance,0)}
function dailyMarket18(){let m=state.market18,day=Math.floor(state.time/1440);if(day<=m.day)return;m.day=day;let season=Math.floor(day/30)%4;m.index=clamp(m.index+rand(-3,3)+(season===3?1:0)-(m.index>105?1:m.index<95?-1:0),80,135);for(let d of [...Object.values(gearCatalog),...Object.values(goods),{name:'식량'}]){if(d.fieldOnly)continue;m.prices[d.name]=clamp(Math.round((m.prices[d.name]??100)*.8+20+rand(-4,4)+(m.demand[d.name]||0)*2),75,135)}m.demand={};for(let r of Object.keys(worldSupply))m.regions[r]=clamp(Math.round((m.regions[r]??100)*.8+20+rand(-8,8)),80,125);for(let l of m.loans){if(!l.balance)continue;if(day>=l.nextInterest){let interest=Math.ceil(l.balance*l.rate/100);l.balance+=interest;l.nextInterest+=30;log('대출 이자 발생 · '+money(interest))}}m.crisis=state.fund<300&&(debt18()>0||arrearsTotal()>0)?m.crisis+1:0;if(m.crisis===3)log('경영 위기 · 마레트와 재정 상황을 점검하세요.');m.history.push({day,index:m.index});m.history=m.history.slice(-30)}
const daily17e=dailyEconomy;dailyEconomy=function(){daily17e();dailyMarket18()};
function loan18(amount){let m=state.market18;if(state.dialogue||![3000,10000,20000].includes(amount)||debt18()+amount>30000||m.crisis>=3)return;let day=Math.floor(state.time/1440),rate=levels18[m.level].rate;if(!cash(amount,'대출 원금','길드 운영 자금 대출'))return;m.loans.push({id:m.next++,balance:amount,rate,opened:day,nextInterest:day+30});log('운영 자금 대출 · '+money(amount));save();render()}
function repay18(id,full){let l=state.market18.loans.find(x=>x.id===id);if(!l||l.balance<=0||state.dialogue)return;let n=Math.min(l.balance,state.fund,full?l.balance:1000);if(n<=0||!cash(-n,'대출 상환','대출 #'+id+' 상환'))return;l.balance-=n;log('대출 상환 · '+money(n));save();render()}
