function marketPanel18(){let m=state.market18;return `<h2>경제 · 금융</h2><p class="muted">게임용 경제 시뮬레이션 · 가격은 매일 갱신됩니다. 대출은 게임 내 가상 계약입니다.</p><div class="grid"><div class="card"><small>물가 지수</small><b class="ops-value">${m.index}</b></div><div class="card"><small>순자금 (현금−부채)</small><b>${fmtSigned(state.fund-debt18())}</b></div><div class="card"><small>대출 잔액</small><b>${money(debt18())}</b></div><div class="card"><small>경영 위기 연속 일수</small><b>${m.crisis}일</b></div></div><div class="card"><h3>난이도</h3>${Object.entries(levels18).map(([k,v])=>`<button class="wide ${m.level===k?'primary':''}" onclick="level18('${k}')">${v.name} · 신규 파견 난도 ${Math.round(v.risk*100)}% · 신규 대출 30일 이자 ${v.rate}%</button>`).join('')}<small>이미 파견된 의뢰와 기존 대출 금리는 변경되지 않습니다.</small></div><div class="card"><h3>마레트의 재정 상담</h3>${m.crisis>=3?'<p class="warn">경영 위기 · 신규 대출 중단. 기존 의뢰 정산과 지출 조정으로 회복하세요.</p>':''}<p>대출 한도: 3 G · 잔여 ${money(Math.max(0,30000-debt18()))}</p>${[3000,10000,20000].map(n=>`<button class="wide" onclick="loan18(${n})" ${debt18()+n>30000||m.crisis>=3?'disabled':''}>${money(n)} 대출</button>`).join('')}${m.loans.filter(l=>l.balance>0).map(l=>`<div class="log"><b>계약 #${l.id} · ${money(l.balance)}</b><p>30일 이자 ${l.rate}% · 다음 이자까지 ${Math.max(0,l.nextInterest-m.day)}일</p><div class="actions"><button onclick="repay18(${l.id},false)">1회 10 S 이하 상환</button><button onclick="repay18(${l.id},true)">가능한 전액 상환</button></div></div>`).join('')}<small>이자는 미상환 잔액에 가산되며 대출 원금과 상환은 재정 장부에 기록됩니다.</small></div><div class="card"><h3>시장 시세</h3><p>식량 5개 · ${money(foodPrice18())}</p>${Object.entries(goods).filter(([k,d])=>!d.fieldOnly).map(([k,d])=>`<div class="row"><span>${esc(d.name)}</span><b>${money(price18(d))}</b></div>`).join('')}<button class="wide" onclick="showInventory('상점')">토비아스의 상점</button></div><div class="card"><h3>지역별 교역 시세</h3>${Object.keys(worldSupply).map(r=>`<div class="log"><b>${esc(r)}</b><p>구매 ${goods[worldSupply[r]].name} · ${money(tradePrice18(r,worldSupply[r],'buy'))}<br>판매 ${goods[worldDemand[r]].name} · ${money(tradePrice18(r,worldDemand[r],'sell'))}</p></div>`).join('')}<small>의뢰 등록 시 견적 고정 · 이동 및 준비 비용 별도</small></div><div class="card"><h3>최근 물가 기록</h3>${m.history.slice().reverse().map(x=>`<div class="row"><span>${x.day+1}일차</span><b>${x.index}</b></div>`).join('')||'<p>아직 일일 변동 기록 없음</p>'}</div>`}
const render17e=render;render=function(){render17e();if(!state||state.dialogue)return;let m=$('main');if(screen==='금융'){m.innerHTML=marketPanel18();$('nav button:nth-child(5)')?.classList.add('active')}else if(['길드','운영','도시','더보기'].includes(screen)){m.insertAdjacentHTML('afterbegin',`<button class="wide" onclick="go('금융')">경제 · 금융 · 물가지수 ${state.market18.index} · 부채 ${money(debt18())}</button>`)}};


// v1.9 — optional audiovisual presentation; no simulation time changes.
const avKey19='asteria-av19';let av19={music:false,sfx:true,volume:35,speed:'normal',motion:true};try{const v=JSON.parse(localStorage.getItem(avKey19)||'null');if(v&&typeof v==='object')av19={...av19,...v}}catch(e){};
let audio19=null,musicTimer19=null,musicStep19=0,typing19=null,lastLine19='',lastScreen19='',queue19=[];
function audioReady19(){try{audio19??=new (window.AudioContext||window.webkitAudioContext)();if(audio19.state==='suspended')audio19.resume().catch(()=>{});return audio19}catch(e){return null}}
