function scheduleRun30(){if(running30||state.dialogue)return;running30=true;let start=state.time;try{for(let i=0;i<3;i++){if(state.dialogue)break;let kind=schedule30[i],people=state.people.filter(available);if(kind==='quest'){let q=state.quests.filter(q=>q.status==='open'&&!q.trade&&q.duration<=480).sort((a,b)=>a.difficulty-b.difficulty)[0];if(q&&people.length&&state.food>=Math.max(1,Math.ceil(q.duration/480))){let p=people.sort((a,b)=>b.skill-a.skill)[0];let tmp=document.createElement('div');tmp.hidden=true;tmp.innerHTML=`<input type="checkbox" name="party" value="${p.id}" checked>`;document.body.append(tmp);try{dispatch(q.id)}finally{tmp.remove()}}}else if(kind==='training'){for(let p of people){if(p.fatigue>=75)continue;let n=statNames.filter(n=>p.stats[n]<p.potential[n]).sort((a,b)=>p.stats[a]-p.stats[b])[0];if(n){p.training=n;p.jobEnd=state.time+120;p.status='훈련';log(p.name+' '+n+' 훈련 시작.')}}}else if(kind==='rest'){for(let p of state.people.filter(p=>currentMember(p)&&p.status==='대기')){p.status='휴식';p.jobEnd=state.time+480;log(p.name+' 휴식 시작.')}}advance(480);if(interrupt||state.dialogue)break;}result30=`${Math.round((state.time-start)/60*10)/10}시간 진행 · ${interrupt?'중요 소식 확인':'일정 종료'}`;save()}finally{running30=false;render()}}
