function recruitArtPath37(p){if(!p.art37){let a=recruitArt37.filter(x=>x[1]===p.profile?.gender);if(!a.length)a=recruitArt37;let m=a.filter(x=>x[2].includes(p.profile?.job));if(m.length)a=m;let h=0;for(let c of String(p.id)+'|'+p.name)h=(Math.imul(h,31)+c.charCodeAt(0))>>>0;p.art37=a[h%a.length][0]}return 'assets/recruits/'+String(p.art37).padStart(2,'0')+'.webp'}
portrait=function(n){let direct=portraitPath(n);if(direct)return `<div class="portrait"><img src="${esc(direct)}" alt="${esc(n)}" decoding="async"></div>`;let p=state&&[...(state.people||[]),...(state.applicants||[])].find(x=>x.name===n&&x.generated);if(!p)return avatar32(n);return `<div class="portrait"><img src="${esc(recruitArtPath37(p))}" alt="${esc(n)}" decoding="async"></div>`;};
