function newsIssue33(day){let n=newsState33(),old=n.editions.find(x=>x.day===day);if(old)return old;let lo=(day-1)*1440,hi=day*1440;let prev=state.logs.filter(x=>x.time>=lo&&x.time<hi),morning=state.logs.filter(x=>x.time>=hi&&x.time<=state.time);let ledger=state.economy.ledger.filter(x=>x.time>=lo&&x.time<hi);let finished=state.quests.filter(q=>q.finished>=lo&&q.finished<hi);let net=ledger.reduce((a,x)=>a+x.delta,0);let market=state.market18?.history||[],now=market.find(x=>x.day===day),before=market.find(x=>x.day===day-1);let articles=[];if(now&&before){let d=now.index-before.index;articles.push({title:'벨로른 시장',body:d?'물가 지수 '+(d>0?'+':'')+d+'p · 현재 '+now.index:'물가 지수 변동 없음 · '+now.index})}let pending=state.story.pending,ev=pending&&storyEvents.find(x=>x.id===pending.id);if(ev)articles.push({title:'오늘의 사건',body:ev.title+' · 길드장의 확인을 기다립니다.'});let important=[...morning,...prev].filter(x=>/실종|미귀환|사망|구조 성공|결혼|출산|입양|은퇴|경영 위기|경쟁.*계약|계약을 선택|재난|범람|폭설|화재|폭염|영웅/.test(x.text));for(let x of important){if(articles.length>=3)break;if(!articles.some(a=>a.body===x.text))articles.push({title:'현장·생활 소식',body:x.text.replace(/^조이: /,'지아: ')})}if(!articles.length)articles.push({title:'오늘의 소식',body:'기록된 주요 사건이 없습니다.'});let issue={day,articles,success:finished.filter(q=>q.status==='success').length,failed:finished.filter(q=>q.status==='failed').length,net,applicants:state.applicants.length,first:day===0};n.editions.unshift(issue);return issue}
function newsMarkup33(e){return `<article class="paper33"><small>${esc(date(e.day*1440+480).split(' · ')[0])} · 제${e.day+1}호</small><h1>아스테리아 일보</h1><div class="paper-rule33"></div>${e.articles.map(a=>`<section><h3>${esc(a.title)}</h3><p>${esc(a.body)}</p></section>`).join('')}<div class="paper-rule33"></div><h3>${e.first?'길드 현황':'어제의 길드'}</h3><div class="newsstats33"><div><small>의뢰 성공</small><b>${e.success}건</b></div><div><small>순현금흐름</small><b>${e.net>0?'+':''}${money(e.net)}</b></div><div><small>현재 지원자</small><b>${e.applicants}명</b></div></div>${e.failed?`<small>미완료 ${e.failed}건</small>`:''}</article>`}
