const render32base33=render;render=function(){render32base33();if(!state||state.dialogue)return;let m=$('main');if(!m)return;let n=newsState33(),day=Math.floor(state.time/1440);if(state.introDone&&state.time%1440>=480&&!n.editions.some(x=>x.day===day)){newsIssue33(day);save()}if(screen==='신문'){m.innerHTML=`<button class="back32" onclick="go('길드')">‹ 길드</button><h2>신문</h2><label class="newsopt33"><input type="checkbox" ${n.auto?'checked':''} onchange="toggleNews33(this.checked)"> 아침 자동 표시</label>${n.editions.map((e,i)=>`<details class="newsarchive33" ${i===0?'open':''}><summary>제${e.day+1}호 · ${esc(date(e.day*1440+480).split(' · ')[0])}</summary>${newsMarkup33(e)}</details>`).join('')||'<p>아직 발행된 신문이 없습니다.</p>'}`;return}if(screen!=='길드')return;let menu=m.querySelector('.menu32');if(menu)menu.insertAdjacentHTML('beforeend','<button onclick="showNews33()">신문</button>');let e=n.editions.find(x=>x.day===day);if(n.auto&&e&&n.readDay<day){let d=document.createElement('dialog');d.className='newspaper33';d.innerHTML=newsMarkup33(e)+`<button class="primary wide" onclick="closeNews33(${day})">하루 시작</button>`;d.addEventListener('cancel',x=>{x.preventDefault();closeNews33(day)});m.append(d);if(d.showModal)d.showModal();else d.setAttribute('open','')}};
