const residents34=[['토비아스 벨트란','상점','여행 장비는 필요한 만큼만 준비하는 게 좋습니다.'],['토마스 베른','시장','요즘은 물자의 시세를 잘 살펴야 합니다.'],['리네아','약초상','약초는 계절에 따라 향도 달라져요.'],['엘로디아','치료원','몸이 보내는 신호를 무시하지 마세요.'],['가렌','장비점','장비는 오래 쓰려면 손질이 중요하지요.'],['마리안','광장','오늘은 시장에 사람들이 많네요.'],['이베르트','영웅협회','현장의 기록은 다음 모험에도 도움이 됩니다.'],['베르단','영웅협회','무리하지 않는 것도 모험가의 실력이지요.'],['피노','광장','오늘도 전할 편지가 한가득이에요.'],['셀마','행정청','주민들의 이야기를 듣는 것도 중요한 일이에요.'],['도란','항구','길을 떠나기 전에 물자부터 확인해야 합니다.'],['에린 로웰','길드','오늘은 업무를 저희에게 맡겨 주세요.'],['로웬 하르트','길드','위험한 의뢰는 내가 먼저 살펴볼게.'],['마레트 에스카르','길드','장부는 매일 정리하고 있습니다.'],['테오 바실','길드','새로운 장비를 살펴보는 중이에요.'],['에반 로르크','광장','다음 탐사에 필요한 지도를 확인하고 있어요.'],['미레나 벨라','광장','출발 전에 날씨와 지형을 확인하는 편이에요.'],['노엘','광장','오늘은 잠깐 쉬고 있어요.'],['세린','광장','마을을 둘러보는 중이에요.']];
function life34(){return state.life34??={schedule:['길드 업무','경영 공부','마을 교류','휴식'],run:null,last:null,stats:{경영:20,지식:20,마법:10,체력:30,견문:10,스트레스:0},relations:{},wallet:500,weekly:[],meet:null,guide:true}}
function set34(i,v){let l=life34();if(l.run||!acts34.includes(v))return;l.schedule[i]=v;save();render()}
