let batch34=false,timer34=null;
const dailyBase34=(...args)=>daily32(...args);
function week34(){let l=life34(),r=l.run;if(!r)return 0;return Math.min(4,Math.floor(Math.max(0,Math.floor(state.time/1440)-r.start)/7))}
function grow34(a){let l=life34(),s=l.stats;let map={'길드 업무':'경영','경영 공부':'지식','마법 공부':'마법','체력 단련':'체력','여행':'견문'};if(map[a])s[map[a]]=Math.min(100,s[map[a]]+1);s.스트레스=clamp(s.스트레스+(['휴식','자유 활동','마을 교류'].includes(a)?-3:2),0,100)}
