function begin34(){let l=life34();if(l.run||blocked34()||!state.introDone)return;let d=Math.floor(state.time/1440),end=Math.min(1200,(Math.floor(d/30)+1)*30);l.run={start:d,end,weekFund:state.fund,wallet41:l.wallet,energy41:init32().energy,fund:state.fund,done:state.completed,rep:state.rep,stats:{...l.stats},rels:Object.fromEntries(Object.entries(l.relations).map(([k,v])=>[k,v.aff])),days:0,weeks:0,lastGrowth:-1,lastDecision:-1};l.last=null;save();continue34()}
function finish34(){let l=life34(),r=l.run;if(!r)return;l.last={days:r.days,success:state.completed-r.done,net:state.fund-r.fund,rep:state.rep-r.rep,stats:Object.entries(l.stats).map(([k,v])=>[k,v-r.stats[k]]).filter(x=>x[1]),relations:Object.entries(l.relations).map(([k,v])=>[k,v.aff-(r.rels[k]||0)]).filter(x=>x[1])};l.run=null;save();screen='길드';render()}
