function townEvent414(n){let p=residents34.find(x=>x[0]===n),e=special414[n],d=townExtra414();if(!townReady413()||!p||!residentAvailable34(p)||!e||relation34(n).aff<8||d.done[n])return;d.done[n]=true;relation34(n).aff=clamp(relation34(n).aff+5,0,100);addStat40(e[4],2);townLine413=e[3];townRecord413(n+' · '+e[0]+' 완료');render()}
