const render414base=render;render=function(){render414base();if(!state||state.dialogue||batch34||!townReady413())return;let m=$('main');if(!m)return;if(screen==='소지품'){m.insertAdjacentHTML('beforeend',`<div class="actions">${['따뜻한 식사','빵','과일 타르트'].filter(k=>personal40().items[k]>0).map(k=>`<button onclick="townUse413('${k}')">${k} 먹기</button>`).join('')}${personal40().items['여행복']>0?`<button onclick="outfit40('여행복')">여행복 착용</button>`:''}</div>`);return}if(screen!=='외출')return;if(!townPlace413){let b=[...m.querySelectorAll('.townmap413 button')].find(x=>x.textContent.includes('축제 광장'));if(b&&!festivalOpen414())b.querySelector('small').textContent='축제는 계절 마지막 5일에 열립니다.';return}let place=townPlace413,extra=visits414[place],people=m.querySelector('.townpeople413');if(extra&&people){people.innerHTML=extra.map(n=>[residents34.findIndex(x=>x[0]===n),n]).filter(([i])=>i>=0&&residentAvailable34(residents34[i])).map(([i,n])=>`<button onclick="townSelect413(${i})">${portrait(n)}<span>${esc(n)}</span></button>`).join('')}let n=townPerson413,e=special414[n],d=townExtra414(),panel=m.querySelector('.townconversation413');if(panel&&n){if(e&&!d.done[n]&&relation34(n).aff>=8)panel.insertAdjacentHTML('beforeend',`<div class="event414"><small>특별한 이야기</small><h3>${esc(e[0])}</h3><p>${esc(e[1])}</p><button onclick="townEvent414(${esc(JSON.stringify(n))})">${esc(e[2])}</button></div>`);if(relation34(n).aff>=15)panel.insertAdjacentHTML('beforeend',`<button class="wide" onclick="townInvite414(${esc(JSON.stringify(n))})" ${d.invites[n]===townDay413()||life34().wallet<15?'disabled':''}>함께 차 마시기 · 15C</button>`)}if(place==='축제 광장')m.insertAdjacentHTML('beforeend',festivalOpen414()?`<section class="event414"><h3>계절 축제</h3><p>광장에서 공연과 노점을 즐길 수 있다.</p><button class="wide" onclick="festival414()" ${d.festival[Math.floor(townDay413()/30)]||life34().wallet<20?'disabled':''}>축제 즐기기 · 20C</button></section>`:'<p>축제는 계절 마지막 5일에 열립니다.</p>')};render();

// v4.20: personal relationships, independent from NPC canon.
function bonds415(){return personal40().bonds415??={dates:{},visits:{},partner:null,married:null,anniversary:null,celebrated:{},memories:[]}}
function bondPeople415(){return [...new Set([...residents34.filter(residentAvailable34).map(p=>p[0]),...state.people.filter(p=>p.generated&&p.status==='대기'&&p.profile?.age>=18).map(p=>p.name)])]}
function romance415(n){let p=state.people.find(p=>p.name===n);return !!(p?.generated&&p.profile?.age>=18&&p.status==='대기'&&!p.partner&&!p.spouse&&!p.family?.spouse)}
function bondLog415(n,t){let b=bonds415();b.memories.unshift({day:townDay413(),name:n,text:t});b.memories=b.memories.slice(0,80);townRecord413(n+' · '+t)}
function bondAction415(i,kind){let n=bondPeople415()[i],b=bonds415(),day=townDay413();if(!townReady413()||!n)return;let r=relation34(n),d=townData413().daily,key='bond:'+n;if(d[key]===day)return;let msg='';if(kind==='talk'){r.aff=clamp(r.aff+2,0,100);r.talks++;msg=r.aff>=30?'서로의 일상과 앞으로의 꿈을 이야기했다.':'서로의 하루에 대해 이야기했다.'}else if(kind==='visit'){if(r.aff<30)return;r.aff=clamp(r.aff+4,0,100);b.visits[n]=day;addStat40('스트레스',-3);msg='길드에 초대해 함께 차를 마셨다.'}else if(kind==='confess'){if(!romance415(n)||r.aff<60||b.partner||b.married)return;b.partner=n;msg='서로 마음을 확인하고 교제를 시작했다.'}else if(kind==='date'){if(b.partner!==n||!romance415(n)||life34().wallet<25)return;life34().wallet-=25;r.aff=clamp(r.aff+5,0,100);b.dates[n]=(b.dates[n]||0)+1;addStat40('스트레스',-5);msg='마을을 산책하고 함께 식사했다.'}else if(kind==='marry'){if(b.partner!==n||b.married||!romance415(n)||r.aff<90||(b.dates[n]||0)<3||life34().wallet<500)return;life34().wallet-=500;b.married=n;b.anniversary=day;msg='두 사람의 결혼식을 올렸다.';if(!personal40().endings.includes('사랑하는 사람과 함께하는 삶'))personal40().endings.push('사랑하는 사람과 함께하는 삶')}else if(kind==='anniversary'){if(b.married!==n||day<=b.anniversary||(day-b.anniversary)%120!==0||b.celebrated[day])return;b.celebrated[day]=true;msg='결혼기념일을 함께 보냈다.';addStat40('스트레스',-8)}else return;d[key]=day;bondLog415(n,msg);render()}
const topics415={'토마스 베른':['장사에서 중요한 것은 무엇인가요?','손님이 다시 찾아올 이유를 만드는 일이지요.'],'리네아':['요즘 즐겨 마시는 차는?','저녁에는 향이 은은한 차를 마셔요.'],'피노':['쉬는 날에는 무엇을 해요?','편지 없이 느긋하게 길을 걷고 싶어요.'],'에반 로르크':['탐사에서 가장 중요한 것은?','돌아올 길을 기억하는 일입니다.'],'미레나 벨라':['훈련이 끝나면 무엇을 해요?','조용히 쉬는 시간이 좋아요.'],'노엘':['여행에서 기억에 남는 것은?','낯선 마을에서 만나는 사람들이지.'],'세린':['어떤 하루가 좋은가요?','서두르지 않고 산책할 수 있는 하루요.']};
function extraTalk415(){let n=townPerson413,p=residents34.find(x=>x[0]===n);if(!p||!residentAvailable34(p)||!townReady413())return;let d=townData413().daily,k='extra:'+n;townLine413=topics415[n]?.[1]||'요즘은 평범한 하루가 소중하게 느껴져요.';if(d[k]!==townDay413()){d[k]=townDay413();let r=relation34(n);r.aff=clamp(r.aff+2,0,100);r.talks++;bondLog415(n,'일상 이야기')}render()}
const render415base=render;render=function(){render415base();if(!state||state.dialogue||batch34||!townReady413())return;let m=$('main');if(!m)return;if(screen==='길드'&&!blocked34()&&!life34().run){let q=m.querySelector('.quiet40');if(q)q.insertAdjacentHTML('afterbegin',`<button onclick="go('인연')">인연</button>`)}if(screen==='외출'&&townPerson413){let panel=m.querySelector('.townconversation413');if(panel)panel.insertAdjacentHTML('beforeend',`<button class="wide" onclick="extraTalk415()">${esc(topics415[townPerson413]?.[0]||'요즘 일상에 대해')}</button>`)}if(screen!=='인연')return;let b=bonds415(),day=townDay413();m.innerHTML=back40()+`<h2>인연</h2>${b.married?`<p>배우자 · ${esc(b.married)}</p>`:b.partner?`<p>연인 · ${esc(b.partner)}</p>`:''}<p class="muted">기존 인물은 우정 중심으로, 새로 영입한 성인 모험가는 연애 가능 여부를 확인한 뒤 교류합니다.</p>${bondPeople415().map((n,i)=>{let r=relation34(n),used=townData413().daily['bond:'+n]===day,actions=[['talk','이야기 나누기',true],['visit','길드에 초대',r.aff>=30],['confess','마음 전하기',romance415(n)&&r.aff>=60&&!b.partner&&!b.married],['date','데이트 · 25C',b.partner===n&&romance415(n)&&life34().wallet>=25],['marry','결혼 · 5S',b.partner===n&&!b.married&&romance415(n)&&r.aff>=90&&(b.dates[n]||0)>=3&&life34().wallet>=500],['anniversary','결혼기념일',b.married===n&&day>b.anniversary&&(day-b.anniversary)%120===0&&!b.celebrated[day]]];return `<details class="bond415"><summary><div class="person">${portrait(n)}<div><b>${esc(n)}</b><br><small>${b.married===n?'배우자':b.partner===n?'연인':r.aff>=30?'친구':'지인'} · 친밀도 ${r.aff}</small></div></div></summary><div class="actions">${actions.filter(x=>x[2]).map(([k,t])=>`<button onclick="bondAction415(${i},'${k}')" ${used?'disabled':''}>${t}</button>`).join('')}</div></details>`}).join('')}<details><summary>함께한 기억</summary>${b.memories.map(x=>`<p>${esc(x.name)} · ${esc(x.text)}</p>`).join('')||'<p>아직 기록이 없습니다.</p>'}</details>`};render();

// v4.20: correspondence, autonomous social visits and seasonal life (game-only preferences).
const gifts416=['작은 꽃다발','허브차','여행 수첩','조개 장식','과일 타르트','장비 손질 도구'];
const tastes416={'토비아스 벨트란':2,'토마스 베른':1,'리네아':1,'엘로디아':1,'가렌':5,'마리안':0,'이베르트':2,'베르단':5,'피노':4,'셀마':2,'도란':3,'에린 로웰':4,'로웬 하르트':5,'마레트 에스카르':2,'테오 바실':2,'에반 로르크':2,'미레나 벨라':1,'노엘':3,'세린':0};
const seasons416=['봄','여름','가을','겨울'];
const events416=[['꽃이 피는 광장','이웃들과 광장의 꽃을 돌보며 봄을 맞았다.','감수성'],['항구의 여름 저녁','항구의 저녁 바람을 맞으며 작은 공연을 즐겼다.','견문'],['가을 수확 장터','수확물을 나누고 장터의 이야기를 들었다.','경영'],['겨울의 등불','이웃들과 따뜻한 차를 나누고 등불을 밝혔다.','사교성']];
function hash416(n){return [...String(n)].reduce((a,c)=>(Math.imul(a,31)+c.codePointAt(0))>>>0,17)}
function social416(){return personal40().social416??={last:-1,inbox:[],serial:0,given:{},known:{},birthdays:{},seasonal:{}}}
function birthday416(n){let p=state.people.find(x=>x.name===n);if(p?.generated&&Number.isInteger(p.life15?.birthday))return p.life15.birthday%120;return hash416(n)%120}
function favorite416(n){return gifts416[tastes416[n]??hash416(n)%gifts416.length]}
