// v4.37 — fixed ten-year campaign; no children or succession.
function legacy435(){return state.legacy435??={records:[],celebrated:{},lastFamily:-1,retireVisits436:{}}}
function record435(text){legacy435().records.unshift({day:townDay413(),text});log(text)}
function age435(p){return Number.isFinite(p.profile?.age)?p.profile.age+Math.max(0,Math.floor((townDay413()-Math.floor((p.joined??p.arrived??0)/1440))/120)):null}
function years435(){return Math.floor(townDay413()/120)}
