function family435(kind){if(kind!=='meal'||!townReady413()||!state.introDone)return;let d=legacy435(),n=spouse435(),day=townDay413();if(!n||d.lastFamily===day||life34().wallet<25)return;life34().wallet-=25;addStat40('스트레스',-5);let r=relation34(n);r.aff=clamp(r.aff+2,0,100);record435(n+'와 함께 식사했다.');d.lastFamily=day;save();render()}
