function visitRetired436(id){let d=legacy435(),p=state.people.find(p=>p.id===id),day=townDay413();d.retireVisits436??={};if(!p||p.retired435==null||!townReady413()||day-(d.retireVisits436[id]??-120)<30)return;d.retireVisits436[id]=day;record435(p.name+'이 길드를 방문해 옛 동료들과 이야기를 나눴다.');save();render()}
function legacyPanel435(){let d=legacy435(),day=townDay413(),n=spouse435(),ready=townReady413();return back40()+`<h2>생애와 길드 연대기</h2><div class="legacy435"><section><img class="scene30" src="${scenes30.rest}" alt="생활 공간"><h3>지아의 삶</h3><p>길드 운영 ${years435()}년 경과</p>${n?`<div class="person">${portrait(n)}<b>${esc(n)}</b></div><button onclick="family435('meal')" ${!ready||d.lastFamily===day||life34().wallet<25?'disabled':''}>함께 식사 · 25C</button>`:'<p>현재 배우자가 없습니다.</p>'}</section><section><h3>길드 창립 기념</h3><button onclick="anniversary435()" ${!ready||!years435()||day%120>=7||d.celebrated[years435()]||state.fund<200?'disabled':''}>창립 기념 · 2S</button><h3>모험가의 생애</h3>${state.people.map(p=>`<div class="row"><span>${esc(p.name)} · ${age435(p)??'나이 미확인'} · ${p.retired435!=null?'은퇴':esc(p.status)}</span>${p.retired435!=null?`<button onclick="visitRetired436(${p.id})" ${!ready||day-(d.retireVisits436?.[p.id]??-120)<30?'disabled':''}>재회</button>`:p.generated&&p.status==='대기'&&age435(p)>=60&&p.name!==n?`<button onclick="retire435(${p.id})" ${!ready||p.arrears>0?'disabled':''}>은퇴</button>`:''}</div>`).join('')}<h3>연대기</h3>${d.records.slice(0,30).map(r=>`<p>${esc(r.text)}</p>`).join('')||'<p>아직 기록이 없습니다.</p>'}</section></div>`}
const LIMIT437=1200*1440;
const normalize437base=normalize;normalize=function(s=state){let v=normalize437base(s);if(!v)return v;if(v.legacy435){let d=v.legacy435;let names=(d.children||[]).map(c=>c.name).filter(Boolean);let obsolete=t=>/입양하여 가족|아이들과 함께 책| · (길드 실무|학문·마법|상업·공예|치유·돌봄) 교육|에게 길드 운영 책임을 인계했다/.test(t)||names.some(n=>t.startsWith(n+'이 ')&&t.endsWith('분야의 일을 시작했다.'));d.records=(d.records||[]).filter(r=>!obsolete(r.text||''));v.logs=v.logs.filter(r=>!obsolete(r.text||''));delete d.children;delete d.successor436;delete d.ageBase;d.celebrated??={};d.retireVisits436??={}}return v};
